    'cli.doctor.unknown' => '알 수 없음',
    'cli.headless.permission_hint' => '  힌트: `-p` 실행 시 모드를 지정하지 않으면 질문하는 `default` 모드로 시작; 비대화형 질문에는 응답할 사람이 없으므로 실패로 종료. 스크립트 실행에서는 --permission-mode bypass-permissions (또는 accept-edits)를 지정하여 계속 진행 가능.',
    'cli.help.screen' => <<<'TXT'
CandyCode — 터미널용 AI 코딩 어시스턴트.

사용법:
  candy-code                       대화형 TUI 시작 (기본)
  candy-code <dir>                 <dir>을 루트로 TUI 시작, <dir>은
                                   존재해야 함 (첫 번째 인자로만)
  candy-code [<dir>] <words…>      TUI 시작 후 해당 단어를 첫
                                   프롬프트로 전송, 예: candy-code fix the bug
  candy-code -c                    최근 세션 계속
  candy-code --resume [<id>]       저장된 세션 재개 (id 없으면 선택기)
  candy-code -p <prompt>           단일 프롬프트 실행 후 종료 (원샷)
  candy-code run "<prompt>"        -p "<prompt>" 별칭 (원샷 모드)
  candy-code --output-format json  기계 가독 JSON 출력 (원샷)
  candy-code --worktree [<name>]   이 세션을 전용 git worktree에서
                                   실행 (없으면 생성)

하위 명령어 (어떤 것도 TUI를 열지 않으며 프로바이더, API 키 또는
터미널을 필요로 하지 않음; serve와 mcp serve는 중단 시까지 실행되며,
나머지는 응답 후 종료 — attach는 예외: 실행 중인 서버의
세션에서 TUI를 실행; acp는 에디터가 연결 해제할 때까지 턴을 실행):
  bundles list           이 디렉터리가 인식하는 플러그인 번들 목록: 이름,
                         버전, 티어, 각 번들이 제공하는 표면 —
                         candy-code가 실행을 거부하는 훅과 .mcp.json
                         포함.
  bundles install <src>  번들 디렉터리 복사 또는 git URL을
                         깊이 1 제한 클론으로 사용자 번들 루트
                         (~/.candy-code/bundles)에 설치, 소유권은 본인만.
  doctor                 이 설치를 검사하고 발견된 모든 문제를 보고:
                         PHP 버전, 세션 저장소와 serve에 필요한
                         확장, 설정 파일, 권한 정책,
                         선택된 프로바이더, 세션 데이터베이스,
                         프로젝트 MCP 구성. 검사 실패 시
                         종료 코드 1.
                         모델 호출 가능한 "doctor" 도구와 별개이며,
                         후자는 터미널의 이미지 프로토콜을 모델에 보고.
  import claude          Claude Code 설정 가져오기 미리보기: Claude의 사용자
                         설정 파일과, --project 지정 시 실행 루트 아래의 .claude
                         설정 파일을 읽은 뒤, permissions의 allow/deny/ask
                         목록을 permissionRules로 변환(엄격한 쪽 우선 —
                         deny가 allow를 이김), model을 매핑하고, 매핑할
                         대상이 없는 키는 skipped로 표시. 확인 전까지 아무것도
                         기록되지 않음: --yes는 출력된 미리보기를 그대로
                         승인하고, 없으면 대화형 터미널에서 확인을 요청.
                         미리보기는 확인 없이 실행 범위를 넓히는 모든 allow 규칙을 표시.
  login <provider>       제공자 로그인: claude-code와 codex는 자체 CLI에
                         터미널을 넘김(토큰은 candy-code를
                         거치지 않음); openai, anthropic, gemini는
                         설정 파일의 providers 블록에 키를 붙여넣기;
                         나머지는 실제 자격 증명 소유자를 표시.
  models                 이 설치에서 선택 가능한 제공자와 각 기본
                         model을 나열; "*"는 선택된 항목을
                         표시.
  session list [--all|--archived|--children] [--limit N]
                         저장된 세션 나열, 고정된 것 먼저 그다음 최신
                         순: id, 마지막 업데이트, kind, turns, provider/model
                         및 name (★는 고정된 행 표시). --children은
                         sub-agent 및 background 행 추가, --archived는
                         보관된 항목 추가, --all은 둘 다 추가; 기본 20행,
                         --limit으로 변경 가능.
  session show <target>  세션 하나의 세부 정보와 대화 기록 출력.
  session rename <target> <title…>
                         세션 이름 변경; target 이후의 단어가
                         제목이 됨.
  session delete <target> [--with-children]
                         세션 삭제. sub-agent 자식도 함께 삭제;
                         분기는 --with-children 없으면 유지.
  session pin|unpin|archive|unarchive <target>
                         세션 고정(목록 상단, 삭제 대상 제외) 또는
                         보관(기본 목록에서 숨김, 데이터 유지).
                         <target>은 id, 이름 또는 고유 id 접두사.
                         일치 없음 시 exit 1, 접두사 모호 시
                         exit 2(후보 목록 출력).
  mcp list               .mcp.json이 선언한 MCP 서버를 나열, 시작
                         하지 않음. 파일 부재, 프로젝트 트리 밖 경로,
                         또는 프로젝트 루트가 신뢰되지 않은 경우
                         대신 보고.
  mcp trust              현재 상태의 프로젝트 .mcp.json 승인: 루트를
                         "trustedProjectMcp"에 추가하고 각 서버의
                         command, args, env를 기록하여, 이후 변경 시
                         재승인 전까지 실행 거부.
                         아무것도 시작하지 않음.
  mcp import claude|opencode|claude-project <path> [--write user]
                         외부 MCP 설정을 변환하여 동등한 .mcp.json
                         블록을 stdout에 출력. 기본은 출력만;
                         --write user는 변환된 항목을 사용자의
                         ~/.candy-code/mcp.json에 추가
                         (이름 충돌 시 전체 쓰기 거부, project
                         계층은 절대 기록하지 않음). 변환 중
                         발생한 이름 변경은 stderr에 표시.
  mcp serve [--root PATH]
                         candy-code 자체를 stdio 기반 MCP 서버로
                         제공: 한 줄에 하나의 JSON-RPC 프레임 입력,
                         한 줄에 하나의 응답 출력, stdin 닫힐 때까지.
                         도구 호출은 읽기 전용 목록(Read, Glob, Grep,
                         Ls, RepoMap)을 workspace 루트에 제한하여,
                         실행 시 PermissionGate와 PreToolUse hook
                         체인을 거침 — 클라이언트가 실행할 수 있는
                         MCP 서버; WebSocket `candy-code serve`는
                         여전히 MCP를 지원하지 않음. 중지 시까지 실행.
  lsp install <language> 한 언어의 고정된 언어 서버 설치:
                         npm 패키지 또는 체크섬 검증된 릴리스 바이너리를
                         홈 아래 비공개 설치 루트에 배치.
                         `lsp list`로 설치 가능한 언어를
                         확인할 수 있음.
  lsp list               설치 가능한 모든 언어 보고: 고정된
                         버전, 서버 설치 위치(또는 미설치 여부),
                         이 머신의 OS 및 아키텍처용 릴리스 존재
                         여부. 아무것도 시작하지 않고,
                         아무것도 다운로드하지 않음.
  self-update [--check] [--rollback] [--allow-unsigned] [--channel=stable|dev]
                         이 phar 설치를 최신 공개 candy-code 릴리스로
                         교체, 교체 전 릴리스 사이드카로 sha256
                         검증; 실행 중인 phar는 <phar>.old로
                         보관하고 --rollback이 정확히 그 사본을
                         한 번 복원. 릴리스 소스에 서명 공개 키가
                         고정된 경우 candy-code.phar.minisig 서명도
                         검증 필요(--allow-unsigned는 해당 단계만
                         생략). --check는 현재 vs 최신만 보고하고
                         업데이트 가능 시 exit 1. Composer 설치는
                         명확히 거부하며, 대신 실행할
                         composer update 명령을 표시. dev 빌드
                         설치는 기본으로 rolling candy-code/dev
                         릴리스를 따름(릴리스의 target 커밋이
                         stamp의 sha와 일치하면 최신)이며 --channel로
                         트레인을 명시적으로 선택.
  serve [--host <ip>] [--port <n>] [--allow-remote] [--allowed-host <list>]
        [--allowed-ips <list>] [--allowed-origin <list>] [--allow-dir-browse]
        [--browse-root <dir>] [--web-root <dir>] [--no-web] [--allow-bypass]
        [--allow-root] [--detach] [--parent-pid <pid>]
        [--tls-cert <file>] [--tls-key <file>]
                         웹 UI가 접속하는 WebSocket + HTTP 서버를
                         전경에서 Ctrl+C까지 실행합니다. 기본으로 127.0.0.1:7420에
                         바인딩하며, 일회용 코드가 포함된 로그인 URL을
                         출력합니다. 이 코드는 브라우저 쿠키로 교환되며, 모든 클라이언트는
                         이 코드 또는 ~/.candy-code/server/token의 토큰이
                         필요합니다(루프백 포함). 옵션:
      --host <ip>        바인딩할 주소 (기본: 127.0.0.1; localhost와 ::1도
                         루프백으로 간주). --allow-remote 없이 다른 주소는
                         거부됩니다.
      --port <n>         바인딩할 포트 (기본: 7420; 0이면 빈 포트 선택).
      --allow-remote     비루프백 --host 허용. --tls-cert 및
                         --tls-key 없이는 평문 HTTP입니다: 앞에 TLS 리버스 프록시를
                         두거나 TLS를 직접 제공하십시오 (아래 참조).
                         0.0.0.0 또는 ::이면 서버가 이 머신의 모든
                         주소에 응답하며, 로그인 URL에 해당 주소가 표시됩니다.
      --tls-cert <file>  리스너가 TLS를 직접 제공하는 데 사용하는 PEM 인증서,
                         --tls-key와 함께 지정합니다. 로그인 URL이
                         https://로 표시되고, 세션 쿠키에 Secure 속성이
                         포함되며, 평문 http:// 클라이언트는 응답을 받지 못합니다.
      --tls-key <file>   --tls-cert용 PEM 개인 키: 그룹·전체 권한이 없는
                         읽기 가능한 파일로, 인증서와 일치해야 합니다.
                         잘못된 키 쌍은 시작 시 거부됩니다.
      --allowed-host <list>
                         서버가 응답하는 추가 호스트 이름(또는 host:port)을
                         쉼표로 구분하여 지정합니다. 예: 이 머신의 DNS 이름.
                         반복 지정 가능.
      --allowed-ips <list>
                         연결을 허용할 클라이언트 IP 또는 CIDR 범위를
                         쉼표로 구분합니다 (예: 1.2.3.4,10.0.0.0/8). 다른
                         주소는 로그인 전 403으로 거부됩니다. 루프백은
                         항상 허용됩니다. 미설정 시 주소 필터 없음.
                         반복 지정 가능.
      --allowed-origin <list>
                         서버 자체 외에 허용하는 추가 브라우저 오리진을
                         쉼표로 구분합니다 (http(s)://host[:port]).
                         반복 지정 가능.
      --allow-dir-browse 로그인한 클라이언트가 새 세션의 시작 디렉터리를
                         선택할 수 있도록 합니다: --browse-root 아래에서
                         디렉터리 이름만 나열 가능 (파일은 불가). 기본: 꺼짐.
      --browse-root <dir>
                         --allow-dir-browse가 제한되는 디렉터리
                         (기본: 홈 디렉터리).
      --web-root <dir>   설치된 sugarcraft/candy-code-web 패키지 대신
                         <dir>에서 웹 UI를 제공합니다.
      --no-web           API와 WebSocket만 제공, UI 파일 없음.
      --allow-bypass     세션이 bypass-permissions 또는 dont-ask 모드로
                         실행되도록 허용 (기본: 거부; 서버 세션은
                         --permission-mode로 변경하지 않는 한 default로 시작).
      --allow-root       root로 실행 허용 (기본: 거부).
      --detach           백그라운드 실행: 포트 바인딩 후 URL과 pid를
                         출력하고 종료; 서버 로그는 상태 디렉터리의
                         server.log에 기록됩니다.
      --parent-pid <pid> 프로세스 <pid> 종료 시 서버를 중지합니다 (개인
                         서버를 시작하는 에디터 또는 TUI용).
                         ext-pcntl, ext-posix, ext-ffi 없이는 시작을
                         거부합니다 (doctor 참조). 포트가 사용 중이거나
                         같은 상태 디렉터리에서 서버가 이미 실행 중이면 종료 코드 1.
  serve status           실행 중인 서버 정보 보고: pid, URL, root, 가동 시간,
                         GET /api/health 응답 여부. 서버가 없으면
                         종료 코드 1.
  serve stop [--force]   서버 중지: SIGTERM, 최대 30초 대기 후 SIGKILL.
      --force            즉시 SIGKILL.
  serve logs [-f]        백그라운드 서버 로그의 끝부분을 출력합니다.
  -f, --follow           서버가 종료될 때까지 추가 로그를 계속 출력합니다.
  serve url [--qr]       새 일회용 코드가 포함된 로그인 URL을 출력합니다.
      --qr              각 로그인 URL을 스캔 가능한 터미널 QR 코드로 렌더링합니다.
  serve token [--rotate] 베어러 클라이언트가 보내는 소유자 토큰을 출력합니다.
      --rotate           토큰을 교체합니다; 실행 중인 서버는 재시작 시까지
                         이전 토큰을 유지합니다.
  attach [<session>] [--url <url>]
                         실행 중인 candy-code serve의 세션에 TUI를
                         연결합니다: 서버가 모든 턴과 도구를 실행하고,
                         이 터미널에서 결과를 표시하며 권한
                         요청에 응답합니다. <session>은 서버 세션의
                         id, 이름 또는 고유 id 접두사입니다;
                         생략 시 새 세션이 생성됩니다. 서버는
                         serve status가 보고하는 서버이며, 토큰은
                         CANDY_CODE_SERVER_TOKEN 또는 상태 디렉터리의
                         토큰 파일에서 가져옵니다. 종료 시 연결이 해제되며,
                         실행 중인 턴은 계속됩니다. 서버가 응답하지 않으면 종료 코드 1.
      --url <url>        <url>의 서버에 연결합니다 (serve가 출력하는
                         주소).
  acp                    Agent Client Protocol 에이전트로 실행: 에디터가
                         (Zed, JetBrains, Neovim) 이 프로세스를 시작하고
                         stdin/stdout으로 JSON-RPC를 통신합니다. 세션은
                         에디터의 프로젝트 루트, 이 설치의 프로바이더와
                         도구로 턴이 실행되며, 에디터가 권한
                         질문에 응답한다. 터미널용 아님: stdout은
                         프로토콜만 전달하고 (나머지는 모두
                         stderr로 전송). 에디터가 stdin을 닫으면 0으로 종료.
  completion bash|zsh|fish
                         셸 자동완성 스크립트를 stdout에 출력, 예:
                         eval "$(candy-code completion bash)".
  usage [7|30|all] [--session <target>]
                         영구 지출 대장을 일별·모델별로 집계:
                         `/usage`가 출력하는 동일한 페이지를 동일한 공유
                         폴드 범위에서. 7과 30은 오늘 포함 온전한 UTC 일,
                         all(또는 피연산자 없음)은 전체 대장을 포함하며,
                         해당 집합 밖의 범위는 조용히 확장되지 않고
                         거부된다. --session은 하나의 세션으로
                         id, 이름 또는 고유 접두사로 좁힌다; --output-format json은
                         페이지가 생성된 팩트 맵을 출력한다. 읽을 수 없는
                         대장은 사유를 밝히고 1로 종료;
                         미가격 모델이 포함된 폴드의 달러는
                         ≥ 하한으로만 표시되며, 단순 합산으로는 표시되지 않는다.

옵션:
  -p, --prompt <text>    명령줄에서 프롬프트 제공 (원샷 모드)
      --output-format <format>
                         출력 형식: "text" (기본), "json" 또는
                         "stream-json" (NDJSON 이벤트, 답변 마지막)
      --root <dir>       현재 디렉터리 대신 <dir>을 프로젝트 루트로 사용.
                         --root=<dir> 형식도 허용 (<dir>이 "-"로 시작할 때
                         사용하는 형식); 생략 불가.
                         여기서 루트를 지정하고 위치 인자로도 지정하면
                         하나가 조용히 이기지 않고 거부된다.
      --config <file>    ~/.candy-code/config.json 대신 <file>에서 설정,
                         권한, 신뢰 훅 루트를 읽는다. --config=<file>도
                         허용. 이미 존재하고, 읽기 가능하고, 소유자가
                         본인이어야 하며, 파일과 그 디렉터리 모두
                         전역 쓰기 가능하면 안 된다 — 권한 정책을
                         담고 있으므로 ~/.candy-code/config.json과 동일한
                         기준을 적용 (etc 또는 /tmp 아래 파일은
                         보통 위 사유 중 하나로 거부됨).
                         파일만 이동: 에이전트, 스킬, 워크플로,
                         세션, 메모리는 ~/.candy-code에 남는다.
      --model <name>     <name>을 대화 모델로 사용, $CANDY_CODE_MODEL과
                         프로바이더 기본값을 재정의. --model=<name>도
                         허용. 모델을 선택하는 것이지 프로바이더를
                         선택하는 것이 아님 — 프로바이더는 여전히 $CANDY_CODE_PROVIDER 또는
                         저장된 `provider` 설정에서 오며, 두 값은
                         독립적인 축이다.
      --permission-mode <mode>
                         설정 파일의 모드 대신 <mode>으로 실행.
                         --permission-mode=<mode>도 허용. 최우선:
                         $CANDY_CODE_PERMISSION_MODE와
                         permissionMode 설정 키를 이긴다. 다음 중 하나:
                         default, accept-edits, plan, auto, dont-ask,
                         bypass-permissions. 미설정 시 TUI와 -p는
                         default로 시작 (쓰기 및 셸 명령 전에 확인);
                         로컬에서 실행된 데몬만
                         bypass-permissions로 시작.
      --max-cost <usd>   이 실행을 <usd> USD 보고 지출로 상한 설정:
                         상한을 초과하는 턴은
                         거부되고 전송되지 않는다. --max-cost=<usd>도 허용.
                         최우선: $CANDY_CODE_MAX_COST와
                         maxCostUsd 설정 키를 이긴다. 소수점 허용, $ 접두사
                         허용 ($2.50); 0과 음수는 "상한 없음"으로
                         해석되지 않고 거부된다. /budget은 실행 중인
                         세션의 상한을 여전히 높이거나 해제한다.
      --max-turns <n>    이 실행을 <n> 도구 루프 단계로 상한 설정: 모든
                         단계를 소진한 턴은 그 위치에서 멈추고 알린다.
                         --max-turns=<n>도 허용. 최우선:
                         maxToolSteps 설정 키를 이긴다 (이 축에는
                         환경 변수가 없음). 양의 정수;
                         0은 "상한 없음"으로 해석되지 않고 거부되며,
                         사용 불가 값은 설정에 조용히
                         위임하지 않고 실행을 거부한다.
      --json-schema <path-or-json>
                         답변을 JSON Schema로 제한: 인라인
                         {"type":"object",...} 문서 또는 해당 파일을
                         가리키는 경로. --json-schema=<value>도 허용;
                         경로가 "-"로 시작할 때 = 형식을
                         사용한다. 스키마 제한 답변을 지원한다고
                         보고한 프로바이더만 요청을 실행하며,
                         그 외에는 제한 없는 답변에 과금하지 않고
                         exit 2로 거부한다. 스키마는 턴의
                         자체 종료 요청을 게이트하며, 도구 루프를
                         계속하는 단계는 자유 (강제 JSON 답변에는
                         도구 호출을 담을 수 없음).
      --append-system-prompt <text-or-@file>
                         이 실행의 시스템 프롬프트에 운영자 규칙을
                         추가: 인라인 텍스트, 또는 규칙을 담은 파일의
                         @path. --append-system-prompt=<value>도 허용;
                         경로가 "-"로 시작할 때 = 형식을
                         "-"로 구분됩니다. 규칙은 하나의
                         개인 지시 블록(fenced)으로 전달되며, 오버라이드가 아닙니다:
                         상위 계층을 대체하거나 격하할 수 없고,
                         텍스트 내 위조 블록 마커는 무력화됩니다.
                         지시 문서와 동일한 크기로 제한됩니다.
                         -p 또는 run 동사에서만 사용 가능: 추가할
                         프롬프트가 없는 실행은 exit 2로 거부되며,
                         지정된 규칙을 조용히 무시하지 않습니다.
  -c, --continue         새 세션 대신 가장 최근 사용된 세션을
                         트랜스크립트 포함하여 다시 엽니다. 이 옵션 없이
                         매 실행마다 새 세션이 열립니다; 빈 입력창에서
                         Up 키는 이전 세션의 프롬프트를 호출합니다.
      --resume [<id|name>]
                         id, 고유 id 접두어 또는 이름으로 저장된 세션을
                         다시 엽니다 (`session list` 참조). 값 없이 실행 시
                         시작 시 세션 선택기가 열립니다; -p와 함께 사용 시
                         대상이 필수입니다 (트랜스크립트가 one-shot을
                         시드하고, 응답이 해당 행에 저장됩니다).
                         --resume=<id> 형식도 허용됩니다. --continue과
      --worktree [<name>]
                         전체 세션을 git worktree
                         main-<name>에서 브랜치 candy-code/<name>으로 실행,
                         최초 사용 시 생성; 이름 없이 실행 시
                         자동 선택된 이름이 부여됩니다. 종료 시
                         커밋도 수정도 없는 worktree는 제거되며,
                         작업이 남아 있으면 유지하고 경로를
                         안내합니다. git work tree 외부 및 `serve`와
      --incognito        아무것도 저장하지 않는 실행: 세션 행 없음,
                         트랜스크립트 없음, 턴 종료 시 자동 메모리 기록 없음.
                         실행 결과는 프로세스에만 존재합니다;
                         이전에 저장된 세션과 메모는 계속 읽을 수 있습니다.
                         --continue 또는 --resume과 함께 사용 시 거부,
                         저장된 세션을 다시 여는 옵션이므로.
      --restricted       코드를 실행할 수 없는 실행: Bash, PtyRun, Task,
                         Workflow, ShellStop, mcp_call이
                         세션 전체 동안 모든 모델 노출 세트에서 제거되며,
                         /permissions로 복원할 수 없습니다. 파일 도구는
                         기존 경로 제한 하에 유지됩니다.
                         --restricted=true|false도 허용하여,
                         맨 플래그를 가진 별칭을 래퍼가 우선할 수 있습니다. 재실행 시 유지.
      --safe-mode        모든 신뢰를 무시하는 실행: 모든 신뢰된
                         프로젝트 루트가 비신뢰로 응답 (hooks, 프로젝트
                         MCP, 명령 셸), 번들 로드 없음,
                         외부 skills, commands, agents 탐색 없음.
                         네이티브 설정, skills, commands는 유지됩니다. 또한
                         --safe-mode=true|false를 허용하여 별칭을
                         우선할 수 있습니다. 재실행 시 유지.
  -h, --help             이 도움말 메시지를 표시
  -v, --version          설치된 버전을 표시하고 종료
      --                 옵션 종료: 이후 모든 인수는 위치 인수로,
                         플래그로 해석되지 않음

환경 변수:
   CANDY_CODE_PROVIDER    사용할 프로바이더: openai, anthropic, claude-code,
                          sglang, bedrock, vertex, custom
   CANDY_CODE_MODEL       모델 이름 (프로바이더 기본값 오버라이드; --model 우선)
   CANDY_CODE_PERMISSION_MODE
                          시작 시 권한 모드, 설정 키를
                          오버라이드 (--permission-mode 우선)
   CANDY_CODE_BACKEND_CMD 커스텀 백엔드 어댑터용 셸 명령, 아래
                          PROSE 계약 하에: stdin으로 JSON 히스토리를 수신, stdout으로
                          응답 텍스트를 기록하며 그대로 사용됨
                          (양 끝만 trim, 내부의 모든 줄바꿈, 빈 줄,
                          들여쓰기는 그대로 유지).
   CANDY_CODE_BACKEND_CMD_STREAM
                          다른 계약 하의 동일 셸 호출, TOKEN
                          STREAM: 한 줄에 토큰 하나, 두 토큰 사이 줄바꿈은
                          프레이밍으로 제거되며, 빈 줄은
                          응답 내 리터럴 줄바꿈입니다. 명령이 토큰을 생성할 때마다
                          콜백이 발동되지만, 읽기 루프는 동기식이므로
                          화면은 토큰별이 아닌 최종 한 번만
                          다시 그립니다. CANDY_CODE_BACKEND_CMD와
                          양방향으로 호환되지 않음 — prose
                          래퍼를 이 변수로 실행하면 모든
                          줄바꿈이 사라지고 빈 줄이 하나로 수축됩니다.
                          둘 다 설정 시 CANDY_CODE_BACKEND_CMD가 우선.
                          둘 다, 미설정, 빈 값, 공백 전용은 모두
                          부재로 간주됩니다.
   CANDY_CODE_DISABLE_PARALLEL_TOOL_CALLS
                          한 턴의 도구 호출을 엄격히 하나씩 실행.
                          동시 디스패치가 기본값이며 비변경 도구만
                          그룹화합니다; 이 변수는 예외 탈출구입니다.
                          "parallelToolCalls": false로
                          ~/.candy-code/config.json에 영속화 가능.
   CANDY_CODE_PARALLEL_TOOL_DEADLINE
                          동시 그룹이 실행 가능한 최대 초,
                          초과 시 잔여 작업이 종료되고 실패 호출로
                          보고됩니다 (기본 90, 1-119 필수; 소수점 절사).
                          "parallelToolDeadlineSeconds"로 영속화 가능.
                          우선순위: 이 변수, 그 다음 영속 키,
                          기본값이 됩니다. 1-119 범위를 벗어나거나 숫자가 아닌 값은
                          설정된 것으로 간주되지 않습니다 — 해당 소스를
                          폐기하지 않고 다음 소스로
                          전달합니다.
   CANDY_CODE_ADVISOR_MODEL
                          `Advisor` 도구가 두 번째 의견을 구하는 모델:
                          도구 없는 완료 호출로, 다른 호출과 동일하게
                          과금됩니다. CANDY_CODE_TITLE_MODEL과 달리
                          저렴한 대체 모델이 없습니다 — 미설정 시 도구가
                          제공되지 않습니다. 시작 시 읽습니다.
   CANDY_CODE_TITLE_MODEL 세션의 첫 교환 후 자동 명명에 사용하는
                          저렴한 모델; 제공자 기본값을 따릅니다.
   CANDY_CODE_SUMMARY_MODEL
                          압축 요약을 작성하는 모델;
                          대화 자체의 모델을 기본값으로 사용하며,
                          프롬프트 캐시를 재사용합니다.
   CANDY_CODE_CONTEXT_PRUNING
                          auto, manual 또는 off: /pruning에서 선택하지
                          않았을 때 세션이 컨텍스트를 정리하는 방식 (기본값 auto).
   CANDY_CODE_MAX_COST    이 실행의 지출 상한, 미국 달러 기준
                          (소수점 허용; 앞의 "$" 허용;
                          --max-cost 우선). 상한을 초과하는 턴은
                          거부됩니다.
   CANDY_CODE_CONNECT_TIMEOUT
                          연결 단계 제한, 초 단위 (소수점
                          허용; 기본값 15.0), 제공자 HTTP
                          전송용. 연결 수립만 제한하며
                          전체 요청 타임아웃이 아닙니다. 연결된
                          스트리밍 서버가 응답 헤더를 보내는 데
                          걸리는 시간은 별도의
                          streamHeaderTimeoutSeconds 설정입니다.
   CANDY_CODE_SEARCH_ENDPOINT
                          내장 WebSearch 도구가 쿼리하는 검색 API.
   CANDY_CODE_SESSION_RETENTION_DAYS
                          양의 정수 일수: 매 실행 시 해당 기간 이상
                          미접촉 세션을 삭제합니다.
   CANDY_CODE_SHARE_UPLOAD_URL
                          폐기된 업로드 호스트: /share는 어디에도
                          업로드하지 않습니다. 설정 시 로컬 내보내기는
                          생성되지만, 응답에서 키를 명시적으로 거부하고
                          /share serve를 안내합니다. 이는 자체 호스팅
                          스냅샷 페이지를 candy-code serve에 게시합니다.
   CANDY_CODE_WORKTREES_DIR
                          팀원별 git 작업 트리가 생성되는
                          기본 디렉터리.
   CANDY_CODE_DISABLE_MOUSE
                          비어 있지 않고 0이 아닌 값은 마우스
                          추적을 완전히 비활성화합니다.
   CANDY_CODE_DISABLE_MOUSE_CLICKS
                          비어 있지 않고 0이 아닌 값은 클릭 제스처를
                          무시하되 휠 스크롤은 유지합니다.
   CANDY_CODE_DISABLE_PROMPT_CACHE
                          비어 있지 않고 0이 아닌 값은 제공자
                          프롬프트 캐시 분할 지점을 비활성화합니다.
   CANDY_CODE_DISABLE_PROMPT_SUGGESTIONS
                          비어 있지 않고 0이 아닌 값은 매 턴 후
                          회색 다음 메시지 제안 (→ 수락)을 비활성화합니다.
   CANDY_CODE_DISABLE_AUTO_MEMORY
                          비어 있지 않고 0이 아닌 값은 자동 메모리가
                          턴 후 영구적 사실을 노트로 저장하는 것과,
                          dream 패스로 압축 저널을 노트에
                          병합하는 것을 비활성화합니다.
   CANDY_CODE_DISABLE_MODEL_METADATA
                          비어 있지 않고 0이 아닌 값은 내장 수치가 없는
                          모델의 크기와 가격을 산정하는 LiteLLM 모델 데이터베이스의
                          읽기 및 갱신을 비활성화합니다.
   CANDY_CODE_NO_UPDATE_CHECK
                          비어 있지 않고 0이 아닌 값은 일일 phar
                          릴리스 확인과 그로 인한 시작 시 업데이트 알림을
                          비활성화합니다; 요청이 프로세스를 떠나지 않으며
                          오래된 캐시된 알림도 더 이상 표시되지 않습니다.
   CANDY_CODE_DISABLE_SYMBOL_MAP
                          비어 있지 않고 0이 아닌 값은 순위가 매겨진
                          심볼 맵을 시스템 프롬프트에서 제외합니다.
   CANDY_CODE_BACKGROUND  light 또는 dark — 적응형 테마가 터미널 배경에
                          대해 판단하는 것을 강제하며,
                          OSC 11 프로브와 COLORFGBG를 건너뜁니다.
   CANDY_CODE_DEBUG_SKILLS
                          비어 있지 않고 0이 아닌 값은 SkillLoader의
                          스킵별 및 거부 디렉터리별 로그를
                          stderr에 다시 출력합니다.
   CANDY_CODE_DEBUG_COMMANDS
                          비어 있지 않고 0이 아닌 값은 CommandLoader의
                          검색 거부 로그를 stderr에 다시 출력합니다.
   CANDY_CODE_DEBUG_RULES 비어 있지 않고 0이 아닌 값은 RuleLoader의
                          검색 거부 로그를 stderr에 다시 출력합니다.
   CANDY_CODE_DEBUG_STREAM
                          비어 있지 않고 0이 아닌 값은 Chat의
                          "onToken observer threw" 로그를 stderr에 유지합니다.
                          디태치 자체는 어느 쪽이든 발생합니다.
   CANDY_CODE_SERVER_HOST `serve`가 바인딩하는 주소 (--host 우선).
   CANDY_CODE_SERVER_PORT `serve`가 바인딩하는 포트 (--port 우선).
   CANDY_CODE_SERVER_ALLOWED_ORIGINS
                          `serve`가 허용하는 쉼표 구분 추가 오리진
                          (--allowed-origin 우선).
   CANDY_CODE_SERVER_ALLOWED_HOSTS
                          `serve`가 응답하는 쉼표 구분 추가 호스트 이름
                          (--allowed-host 우선).
   CANDY_CODE_SERVER_ALLOWED_IPS
                          `serve`가 허용하는 쉼표 구분 클라이언트 IP 또는 CIDR
                          루프백 외 (--allowed-ips 우선).
   CANDY_CODE_SERVER_WEB_ROOT
                          `serve`가 웹 UI를 제공하는 디렉터리 (--web-root
                          우선).
   CANDY_CODE_SERVER_TOKEN
                          `serve`가 요구하는 토큰 — 상태 디렉터리의 토큰
                          대신 사용 (최소 32자; 컨테이너
                          용).
   CANDY_CODE_SERVER_DIR  `serve`가 토큰, 락,
                          디스커버리 레코드, 로그를 보관하는 디렉터리 (기본
                          ~/.candy-code/server; 0700으로 생성).
   CANDY_CODE_SERVER_PARENT_PID
                          `serve`가 함께 종료하는 프로세스 (--parent-pid 우선).
   CANDY_CODE_MCP_DISABLE
                          1, true 또는 yes (대소문자 무시)로 설정 시 프로젝트
                          MCP를 완전히 비활성화: .mcp.json이 없는 것으로 처리,
                          서버를 시작하지 않음. 미설정, 0 또는 기타 값은
                          MCP를 활성화 유지 — 플래그 스타일 변수와 달리,
                          이 세 단어만 인식.
   CANDY_CODE_QUIET_LOGS  1, true 또는 yes (대소문자 무시)로 설정 시
                          error_log() 사이드채널을 프로세스 전체에서 단일
                          싱크에서 차단; 미설정, 0 또는 기타 값은
                          진단 로그를 유지. 실행 시에만 적용, 설정 키 없음.
   CANDY_CODE_REDUCED_MOTION
                          1, true 또는 yes (대소문자 무시)로 설정 시 에이전트
                          스피너를 정적 프레임 하나로 고정 — 모션 민감
                          사용자 및 모션 감소 설정 사용자를 위해. 실행 시
                          한 번만 읽음; 설정 키 없음.
   CANDY_CODE_SD_BASE_URL 미디어 트랜스포트가 연결하는 A1111 스타일 (sdapi)
                          Stable Diffusion 서버의 기본 URL.
                          우선순위: 명시적 코드 오버라이드, 이 변수,
                          그다음 sd.baseUrl 설정.
   CANDY_CODE_MEDIA_RENDER_MODE
                          터미널에서 생성된 이미지를 렌더링하는 방식
                          (ui.imageRenderMode 설정의 환경 변수 레이어;
                          허용 값은 docs/ENVIRONMENT.md 참조).
   CANDY_CODE_ALLOW_ROOT_TESTS
                          candy-code TEST SUITE가 root로 실행되려면 정확히 1로
                          설정; 미설정 또는 기타 값이면 euid 0에서
                          스위트 실행을 거부. candy-code 실행 자체에는
                          영향 없음 — 스위트는 사용자 대상
                          인터페이스가 아님.
   CANDY_CODE_TOOL_INPUT  현재 사용자 스크립트 도구 호출의 전체 인자 맵을
                          JSON 인코딩하여 ~/.candy-code/tools 도구의 모든
                          실행 시 자식 프로세스에 내보냄; 앱이 쓰기만 하고
                          다시 읽지 않으며, 사용자가 직접 설정하지
                          않음.
   CANDY_CODE_OTEL_BATCH_SIZE
                          OTLP 내보내기 배치당 스팬 수
                          (기본 64, 1..2048로 클램프).
   CANDY_CODE_OTEL_TIMEOUT
                          OTLP 내보내기 시도당 허용 시간(초)
                          (기본 3; 음수 또는 잘못된 값은
                          기본값으로 폴백).

   docs/ENVIRONMENT.md에 이 빌드가 읽는 모든 변수와 그
   전체 명세가 정리되어 있음.

종료 코드 (원샷 모드 및 모든 하위 명령):
  0                      프롬프트가 실행되어 응답을 생성했거나,
                         하위 명령이 응답함
  1                      실행 후 실패: 백엔드 오류 (호스트 도달 불가,
                         키 거부, 모델 오류) — 재시도 시 해결 가능 — 또는
                         하위 명령이 실행되었으나 실패함 (진단 검사가 반환
                         FAIL 반환, `session` 동사가 해당 세션을
                         찾지 못함, 신뢰된 .mcp.json 파싱 실패)
  2                      사용법 또는 설정 오류, 아무것도 시도되지 않음,
                         재시도해도 해결 불가: 프롬프트 미제공,
                         인식 불가 플래그, 존재하지 않는 디렉터리를
                         지정한 인자 (프롬프트에는 -p 필요), --root가
                         디렉터리를 지정하지 않음, composer
                         autoload.php 누락, 또는 선택된 프로바이더를
                         생성할 수 없음 — $CANDY_CODE_PROVIDER 또는
                         Ctrl+P "Switch model"로 ~/.candy-code/config.json에
                         저장된 프로바이더.
                         원샷 실행 시 프로바이더가 명시적으로 선택되면
                         오프라인 echo 프로바이더로 폴백하지 않음.
                         하위 명령에 누락 또는 알 수 없는 피연산자
                         (`session`, `mcp bogus`, `completion tcsh`)가
                         전달되면 여기서 보고됨.
  130/143/129             TUI: 신호가 루프를 중단함 — 128+N
                         SIGINT (Ctrl+C), SIGTERM, SIGHUP; 협조적
                         종료(/exit, q)는 여전히 0으로 종료.

예시:
  candy-code -p "Explain the difference between require and include"
  CANDY_CODE_PROVIDER=anthropic CANDY_CODE_MODEL=claude-sonnet-4-20250514 \
    candy-code -p "Write a hello world in Go"
  candy-code run "Write a hello world in Go"
  candy-code doctor
  candy-code models --output-format json | jq '.result.providers'
  eval "$(candy-code completion bash)"
  candy-code serve --port 7420

자세한 정보는 README를 참조:
  https://github.com/detain/sugarcraft/tree/master/candy-code

