    'cli.mcp.usage' => '사용법: candy-code mcp list | candy-code mcp trust | candy-code mcp auth login <server> | candy-code mcp import claude|opencode|claude-project <path> [--write user] | candy-code mcp serve [--root PATH]',
    'cli.models.none_configured' => '구성된 제공자가 없습니다.',
    'cli.models.none_selected' => '선택된 제공자가 없습니다; CANDY_CODE_PROVIDER를 설정하거나 Ctrl+P `Switch model`을 사용하세요.',
    'cli.models.selected_legend' => '* = 선택됨 (CANDY_CODE_PROVIDER 또는 {path}).',
    'cli.noninteractive.answer_not_json' => '응답을 JSON으로 인코딩할 수 없습니다: {error}',
    'cli.noninteractive.append_system_prompt_no_backend' => '제공된 백엔드는 --append-system-prompt를 지원하지 않습니다: 엔진이 아니므로 추가할 시스템 프롬프트가 없습니다',
    'cli.noninteractive.append_system_prompt_too_large' => '--append-system-prompt는 {max}바이트로 제한됩니다; 제공된 규칙은 {bytes}바이트입니다',
    'cli.noninteractive.append_system_prompt_unreadable' => '--append-system-prompt에 읽을 수 없는 파일이 지정되었습니다: {path}',
    'cli.noninteractive.json_schema_invalid' => '--json-schema가 유효한 JSON이 아닙니다: {error}',
    'cli.noninteractive.json_schema_no_backend' => '제공된 백엔드는 --json-schema를 지원하지 않습니다: 엔진이 아니므로 응답을 제약할 제공자가 없습니다',
    'cli.noninteractive.json_schema_not_object' => '--json-schema는 JSON 객체(스키마)여야 합니다; 배열이나 스칼라 값은 해당되지 않습니다',
    'cli.noninteractive.json_schema_unapplied' => '--json-schema로 요청한 스키마가 최종 응답을 제약할 수 없습니다: 이 턴에서 도구가 실행되었으며, 스키마는 첫 번째 요청에만 적용됩니다 (README.md 참조)',
    'cli.noninteractive.json_schema_unreadable' => '--json-schema에 읽을 수 없는 파일이 지정되었습니다: {path}',
    'cli.noninteractive.json_schema_unsupported' => '{name} 제공자는 --json-schema를 지원하지 않습니다: 응답이 구조화된 것으로 과금되지만 제약 없이 도착합니다',
    'cli.noninteractive.no_prompt' => '프롬프트가 지정되지 않았습니다 — -p "<prompt>" 또는 `candy-code run "<prompt>"`를 사용하세요',
    'cli.noninteractive.no_reason_given' => '사유가 지정되지 않았습니다',
    'cli.noninteractive.offline_default' => '구성된 제공자가 없습니다 (CANDY_CODE_PROVIDER, CANDY_CODE_BACKEND_CMD 및 CANDY_CODE_BACKEND_CMD_STREAM 미설정, 영속화된 항목 없음); 오프라인 에코 제공자로 응답합니다.',
    'cli.noninteractive.provider_refusing' => '단일 실행에서 다른 백엔드로 조용히 응답하는 것을 거부합니다 — 제공자 구성을 수정하거나 {remedy}.',
    'cli.noninteractive.provider_remedy_config' => '폴백을 의도적으로 선택하려면 {path}에서 `provider` 항목을 제거하세요 — 이 실행이 선택한 영속화된 Ctrl+P `Switch model` 선택지입니다',
    'cli.noninteractive.provider_remedy_env' => 'CANDY_CODE_PROVIDER를 해제하여 폴백을 의도적으로 선택하세요',
    'cli.noninteractive.provider_unusable' => '제공자 \'{provider}\'을(를) 사용할 수 없습니다: {error}',
    'cli.noninteractive.refusal' => '[{kind}] {tool}이(가) 실행되지 않았습니다 - {reason}',
    'cli.noninteractive.session_end_hook_refused' => 'SessionEnd 훅 `{hook}` 거부됨: {reason}',
    'cli.noninteractive.session_end_refused' => 'SessionEnd 훅 거부됨: {reason}',
    'cli.noninteractive.session_funnel_failed' => '이 실행에서 세션 저장소를 열 수 없습니다; 저장된 기록 없이 응답하며 아무것도 저장되지 않습니다: {error}',
    'cli.noninteractive.session_save_failed' => '세션 저장소가 이 응답을 저장할 수 없습니다; 응답은 완료되었으며 종료 상태는 변경되지 않습니다: {error}',
    'cli.noninteractive.stdin_silent' => 'stdin이 {seconds}초간 응답이 없어 파이프된 컨텍스트가 없는 것으로 처리되었습니다; fd 0을 닫거나 느린 시작 시 첫 바이트 도착 전에 데이터를 공급하세요',
    'cli.noninteractive.stdin_truncated' => '파이프된 stdin이 10MB 상한을 초과했습니다; 잘라냅니다.',
    'cli.noninteractive.turn_hook_blocked' => '턴 훅이 이 프롬프트를 거부하여 전송되지 않았습니다: {reason}',
    'cli.permission.arguments_truncated' => '… (잘림 — {bytes}바이트 미표시)',
    'cli.permission.confirm' => '실행하시겠습니까? [y/N] ',
    'cli.permission.no_tty' => '도구 호출에 권한이 필요하지만 stdin이 터미널이 아니므로 물어볼 대상이 없습니다 — 거부합니다.',
    'cli.permission.no_tty_remedy' => <<<'TXT'
  터미널에서 실행하여 프롬프트를 받거나, 실행에 결정 정책을 지정하세요
  묻지 않고: --permission-mode <mode> (bypass-permissions는 모든 것을 실행),
  또는 .candy-code/config.json에 {tool}의 permissionRules 항목을 추가하세요.
TXT,
    'cli.permission.question' => '도구 호출에 권한이 필요합니다.',
    'cli.permission.refused' => '{tool} 거부됨.',
    'cli.permission.stdin_ended' => '질문에 답하기 전에 stdin이 종료되었습니다 — {tool} 거부합니다.',
    'cli.permission.unrenderable_arguments' => '<인수를 렌더링할 수 없음>',
    'cli.references.missing' => '`references` 항목 {path}이(가) 존재하는 디렉터리가 아니므로 Read, Grep, Glob, Ls가 이를 참조하지 않습니다.',
    'cli.references.redundant' => '`references` 항목 {path}이(가) 세션 작업 공간 내부에 있습니다 — 격리가 이미 이를 포함하므로 두 번째 읽기 루트로 추가되지 않습니다.',
    'cli.references.unusable' => '`references` 항목을 읽을 수 없습니다 — `path`를 가진 객체(또는 일반 경로 문자열)여야 합니다; 이 항목은 건너뛰었습니다.',
    'cli.refuse.bad_mode' => '{source}이(가) \'{value}\'로, 권한 모드가 아닙니다 (기대값: {valid}). 기본 허용 모드로 폴백하는 대신 시작을 거부합니다.',
    'cli.refuse.claude_mcp_arg_entry' => 'claudeMcpArgs에 비스칼라 항목이 있습니다; argv 문자열만 허용',
    'cli.refuse.claude_mcp_args' => '사용자 구성에서 claudeMcpArgs는 스칼라의 JSON 배열이어야 합니다',
    'cli.refuse.claude_mcp_binary' => '사용자 구성에서 claudeMcpBinary는 문자열 경로여야 합니다',
    'cli.refuse.claude_mcp_env' => '사용자 구성에서 claudeMcpEnv는 JSON 객체여야 합니다',
    'cli.refuse.claude_mcp_env_entry' => 'claudeMcpEnv는 문자열 키를 문자열 값에 매핑해야 합니다',
    'cli.refuse.config_bom' => 'UTF-8 바이트 순서 표시로 시작하며, JSON에서 허용되지 않습니다 — 파일을 BOM 없이 UTF-8로 다시 저장하세요',
    'cli.refuse.config_dangling' => '{path}이(가) 존재하지만 읽을 수 있는 파일이 아닙니다 (해결되지 않는 심볼릭 링크). 알 수 없는 권한 정책으로 실행하는 대신 시작을 거부합니다.',
    'cli.refuse.config_is_directory' => '{path}이(가) 존재하지만 읽을 수 있는 파일이 아닙니다 (디렉터리). 알 수 없는 권한 정책으로 실행하는 대신 시작을 거부합니다.',
    'cli.refuse.config_not_json' => '{path}이(가) 사용할 수 있는 JSON이 아닙니다 ({error}). 알 수 없는 권한 정책으로 실행하는 대신 시작을 거부합니다.',
    'cli.refuse.config_not_object' => '최상위 수준이 JSON 객체가 아닙니다',
    'cli.refuse.config_unreachable' => '{path}에 접근할 수 없습니다: {reason}. 해당 경로에 권한 정책이 설정되어 있는지 알 수 없습니다. 알 수 없는 권한 정책으로 실행하는 대신 시작을 거부합니다.',
    'cli.refuse.config_unreadable' => '{path}이(가) 존재하지만 읽을 수 없습니다 (권한을 확인하세요). 알 수 없는 권한 정책으로 실행하는 대신 시작을 거부합니다.',
    'cli.refuse.dangling_directory' => '{dir}은(는) 이 프로세스가 탐색할 수 있는 디렉터리로 해석되지 않는 심볼릭 링크입니다',
    'cli.refuse.foreign_owner' => '{path}은(는) uid {uid}에 속하며, 이 세션이 실행 중인 계정의 소유가 아닙니다. 따라서 해당 파일의 권한 정책과 훅 체인은 다른 사용자의 것입니다. 다른 계정의 정책으로 실행하는 대신 시작을 거부합니다.',
    'cli.refuse.hook_chain' => '{error} 설정된 것과 다른 훅 체인으로 실행하는 대신 시작을 거부합니다.',
    'cli.refuse.hooks_unreachable' => '{path}에 접근할 수 없습니다: {reason}. 해당 경로에 훅이 설정되어 있는지 알 수 없습니다. 알 수 없는 훅 체인으로 실행하는 대신 시작을 거부합니다.',
    'cli.refuse.keybindings' => '키 바인딩 설정을 사용할 수 없습니다: {reason}. 해당 키를 제거하면 기본 제공 바인딩으로 실행됩니다 (/keys 참조에서 확인 가능). 적용되지 않은 키 재정의 상태로 실행하는 대신 시작을 거부합니다.',
    'cli.refuse.max_cost_env' => '$CANDY_CODE_MAX_COST가 \'{value}\'입니다. 지출 상한이 아닙니다. 양의 미국 달러 수치를 입력하세요 (소수점 허용, 앞의 $ 기호 허용). 예: 5 또는 $2.50. 0과 음수는 "상한 없음"으로 해석하지 않고 거부합니다 — 정반대의 요청이기 때문입니다. 표현할 수 없는 큰 수치(1e309, 즉 무한대)도 거부합니다 — 절대 발동하지 않는 상한을 설치하게 되기 때문입니다. 상한 없이 실행하려면 변수를 해제하세요. 요청한 상한 대신 무제한으로 실행하는 대신 시작을 거부합니다.',
    'cli.refuse.max_cost_flag' => '--max-cost가 \'{value}\'입니다. 지출 상한이 아닙니다. 양의 미국 달러 수치를 입력하세요 (소수점 허용, 앞의 $ 기호 허용). 예: 5 또는 $2.50. 0과 음수는 "상한 없음"으로 해석하지 않고 거부합니다 — 정반대의 요청이기 때문입니다. 표현할 수 없는 큰 수치(1e309, 즉 무한대)도 거부합니다 — 절대 발동하지 않는 상한을 설치하게 되기 때문입니다. 상한 없이 실행하려면 플래그를 제거하세요. 요청한 상한 대신 무제한으로 실행하는 대신 시작을 거부합니다.',
    'cli.refuse.max_cost_setting' => '설정의 maxCostUsd가 {value}입니다. 지출 상한이 아닙니다. 양의 미국 달러 수치를 입력하세요. 예: 5 또는 2.5. 상한 없이 실행하려면 해당 키를 제거하세요. 요청한 상한 대신 무제한으로 실행하는 대신 시작을 거부합니다.',
    'cli.refuse.max_turns_flag' => '--max-turns가 \'{value}\'입니다. 단계 상한이 아닙니다. 양의 정수 도구 루프 단계를 입력하세요. 예: 8. 0은 "상한 없음"으로 해석하지 않고 거부합니다 — 정반대의 요청이기 때문입니다. 표현할 수 없는 큰 수치도 거부합니다 — 절대 발동하지 않는 상한을 설치하게 되기 때문입니다. 플래그를 제거하면 maxToolSteps 설정을 따릅니다. 요청한 상한 대신 무제한으로 실행하는 대신 시작을 거부합니다.',
    'cli.refuse.no_home' => '이 프로세스는 사용자의 홈 디렉터리를 확인할 수 없습니다 ($HOME 미설정, $USERPROFILE 미설정, 해당 uid의 passwd 항목 없음). 따라서 ~/.candy-code의 권한 정책과 훅 체인을 찾을 수 없습니다. 누구나 쓸 수 있는 폴백 디렉터리에서 읽는 대신 시작을 거부합니다 — 이 세션이 속한 계정의 HOME을 export하세요.',
    'cli.refuse.no_project_root' => '프로젝트 루트를 확인할 수 없습니다 — 프로세스 작업 디렉터리가 사용할 수 없습니다 (삭제되었거나 읽을 수 없음). --root <dir>을 지정하세요.',
    'cli.refuse.not_searchable' => '{dir}은(는) 이 프로세스가 탐색할 수 없습니다',
    'cli.refuse.project_settings_unusable' => '{path}에서 permissionRules를 읽을 수 없습니다 ({reason}). 알 수 없는 권한 정책으로 실행하는 대신 시작을 거부합니다.',
    'cli.refuse.world_writable' => '{path}은(는) 이 머신의 모든 계정이 쓸 수 있어, 해당 파일의 권한 정책과 훅 체인은 이 사용자의 것이 아닙니다. 누구나 쓸 수 있는 정책으로 실행하는 대신 시작을 거부합니다 — `chmod o-w {path}`.',
    'cli.selfupdate.channel_invalid' => '{value}: candy-code self-update --channel은 stable 또는 dev만 허용합니다.',
    'cli.selfupdate.check_available' => 'candy-code: 업데이트 가능 — 현재 설치 버전 {current}, 최신 릴리스 {latest}. (--check는 보고만 하며, 아무것도 설치하지 않았습니다.)',
    'cli.selfupdate.check_unknown' => 'candy-code: 현재 설치 버전 ({current})과 최신 릴리스 ({latest})을 비교할 수 없습니다.',
    'cli.selfupdate.check_up_to_date' => 'candy-code: 최신 상태 — 현재 설치 버전 {current}, 최신 릴리스 {latest}.',
    'cli.selfupdate.composer_mode' => 'candy-code: self-update는 phar 설치를 교체합니다. 이 복사는 Composer로 설치되어 교체할 phar가 없습니다. 다음으로 업데이트하세요: {command} (전역 설치는 `composer global update sugarcraft/candy-code`를 실행합니다).',
    'cli.selfupdate.composer_mode_root' => 'candy-code: self-update는 phar 설치를 교체합니다. 이 복사는 Composer 루트 패키지로 설치된 sugarcraft/candy-code이며, 교체할 phar가 없고 루트 패키지는 자체 의존성 명령으로 자기 자신을 갱신할 수 없습니다. 다음으로 업데이트하세요: {command} (클론이 새 소스를 가져온 후 vendor 트리를 재빌드합니다).',
    'cli.selfupdate.dir_not_writable' => 'candy-code: phar를 교체할 수 없습니다 — 디렉터리 {dir}에 쓰기 권한이 없습니다.',
    'cli.selfupdate.downgrade_refused' => 'candy-code: 다운그레이드 거부 — 현재 설치 버전 {current}, 최신 릴리스 {latest}. (--rollback은 보관된 복사를 복원합니다. 그 외에는 되돌아가지 않습니다.)',
    'cli.selfupdate.download_failed' => 'candy-code: {asset}을(를) 다운로드할 수 없습니다: {reason}',
    'cli.selfupdate.empty_download' => 'candy-code: {asset} 다운로드에서 바이트가 생성되지 않았습니다.',
    'cli.selfupdate.fetch_failed' => 'candy-code: 릴리스 목록을 읽을 수 없습니다: {reason}',
    'cli.selfupdate.flags_exclusive' => '--check는 보고만 합니다. 단독으로 사용하세요. --rollback이나 --allow-unsigned와 함께 사용하지 마세요.',
    'cli.selfupdate.hash_mismatch' => 'candy-code: 다운로드한 phar의 해시가 {actual}입니다. 사이드카가 서명한 {expected}와 일치하지 않습니다. 교체하지 않았습니다.',
    'cli.selfupdate.hash_unreadable' => '없음 (임시 파일을 읽을 수 없음)',
    'cli.selfupdate.installed' => 'candy-code: self-update가 {path}을(를) 교체했습니다 ({from} -> {to}); 이전 phar는 {old}에 보관되어 있습니다 — `self-update --rollback`으로 1회 복원 가능.',
    'cli.selfupdate.no_dev_release' => 'candy-code: 게시된 dev 릴리스 (tag {tag})에 {phar}과 {sidecar}이(가) 모두 없습니다.',
