    'cli.selfupdate.swap_leftover' => 'candy-code: 이전 self-update가 적용되지 않은 준비된 교체를 {new}에 남겼습니다 (교체 로그에 중단된 시도가 기록되어 있습니다). 이번 실행은 업데이트 전에 준비 상태를 교체합니다.',
