    'cmd.mcp-auth.enable.usage' => '사용법: /mcp enable <server> [--persist]',
    'cmd.mcp-auth.failed' => '✗ 등록 실패: {error}',
    'cmd.mcp-auth.heading' => '**MCP Servers**',
    'cmd.mcp-auth.login-armed' => "↻ `{server}`에 대한 MCP 로그인 시작 — 브라우저 링크를 대기 중입니다.\n\n자식 프로세스가 루프백 포트에 바인딩합니다; TUI가 반응성을 유지하는 동안 브라우저에서 완료하세요. 이 세션의 MCP 클라이언트는 시작 시 저장소를 메모이제이션했으므로, 토큰은 다음 시작 시 적용됩니다; 저장되면 `/mcp list`에 자격 증명이 표시됩니다.",
    'cmd.mcp-auth.login-busy' => '! `{server}`에 대한 로그인이 이미 실행 중입니다 — 먼저 완료하거나 취소하세요 (URL 및 상태는 위 대화 기록에 있습니다).',
    'cmd.mcp-auth.login-code-delivered' => '✓ `{server}` 대기 중인 로그인에 콜백이 전달되었습니다 — 자식 프로세스가 거기서 교환을 완료하며, 결과가 대화 기록에 표시됩니다.',
    'cmd.mcp-auth.login-code-refused' => '! `{server}`에 대한 MCP 로그인 콜백을 전달할 수 없습니다: {reason}',
    'cmd.mcp-auth.login-code-reason-dial' => "대기 중인 로그인의 리스너가 응답하지 않았습니다",
    'cmd.mcp-auth.login-code-reason-host' => '루프백 호스트 `127.0.0.1`과 `localhost`만 허용됩니다',
    'cmd.mcp-auth.login-code-reason-noslot' => '이 호스트에서 해당 서버의 로그인이 현재 대기 중이 아닙니다',
    'cmd.mcp-auth.login-code-reason-port' => '포트가 대기 중인 로그인이 알린 콜백 포트와 일치하지 않습니다',
    'cmd.mcp-auth.login-code-reason-scheme' => '콜백 URL은 로그인 리스너가 바인딩하는 일반 `http` 스킴을 사용해야 합니다',
    'cmd.mcp-auth.login-code-reason-shape' => '형식은 `/mcp login <server> --code <callback-url>`이며 URL은 정확히 하나여야 합니다',
    'cmd.mcp-auth.login-done' => '✓ `{server}`에 대한 MCP 로그인 완료 (종료 코드 {code}). 토큰은 다음 시작 시 첨부됩니다 — 권한이 요청에 포함되려면 새 세션을 시작하세요; `/mcp list`로 패널을 새로고침합니다.',
    'cmd.mcp-auth.login-failed' => <<<'TXT'
✗ `{server}`에 대한 MCP 로그인이 토큰을 저장하지 않고 {code}로 종료되었습니다.

자식 프로세스의 마지막 줄이 위에 있습니다; 셸에서 동일한 흐름(`candy-code mcp auth login {server}`)을 실행하면 전체 오류가 출력되며, 엔드포인트 또는 포트 문제를 디버깅할 수 있습니다.
TXT,
    'cmd.mcp-auth.login-failed-spawn' => "✗ `{server}`에 대한 MCP 로그인 자식 프로세스를 시작할 수 없습니다.\n\n셸 형식을 직접 실행하세요: `candy-code mcp auth login {server}`.",
    'cmd.mcp-auth.login-guidance' => "대화형 로그인은 채팅 턴이 아닌 셸 명령입니다:\n\n  candy-code mcp auth login <server> [token-url] [authorize-url] [registration-url]\n\nPKCE를 사용하는 OAuth 인가 코드 플로우를 실행합니다: 브라우저가\n코드를 셸의 루프백 리스너로 반환하고, 저장된\n토큰은 다음 실행부터 일치하는 http 서버에 자동 첨부됩니다.",
    'cmd.mcp-auth.login-no-entry' => "✗ `mcp auth login {server}`를 포크할 이 프로그램의 진입점을 찾을 수 없습니다.\n\n셸 형식을 직접 실행하세요: `candy-code mcp auth login {server}`.",
    'cmd.mcp-auth.login-served-armed' => "↻ `{server}`의 MCP 로그인이 SERVER 호스트에서 시작되었습니다 — 링크가 아래에 표시됩니다; 본인 머신의 브라우저에서 여세요. 브라우저가 서버의 루프백 리스너에 직접 도달할 수 없습니다: 연결 오류 페이지가 뜨면 해당 페이지 주소를 복사하여 `/mcp login {server} --code <that-url>`를 전송하면 대기 중인 로그인에 콜백이 전달됩니다. 토큰은 다음 실행 시 첨부됩니다; `/mcp list`로 저장된 자격 증명을 확인할 수 있습니다.",
    'cmd.mcp-auth.login-url' => '→ `{server}` 인증을 위해 이 URL을 여세요:\n\n  {url}',
    'cmd.mcp-auth.not-found' => '! `{server}`의 자격 증명을 찾을 수 없습니다.',
    'cmd.mcp-auth.registered' => <<<'TXT'
✓ `{server}` 등록 완료
클라이언트 ID: `{client}`
이 정확한 URL의 http MCP 서버로 보내는 요청에 이 토큰이 자동 첨부되며, 만료 전 갱신됩니다; 이 명령 실행 전에 시작된 서버는 다음 실행 시 적용됩니다.
TXT,
    'cmd.mcp-auth.remove-usage' => '사용법: mcp auth remove <server>',
    'cmd.mcp-auth.reconnect.auth' => '! `{server}`이(가) OAuth 로그인이 필요하다고 보고합니다.',
    'cmd.mcp-auth.reconnect.denied' => '! `{server}`이(가) 거부 패턴에 의해 차단되었습니다.',
    'cmd.mcp-auth.reconnect.drifted' => "실행 이후 MCP 설정이 변경됨 — 재연결 거부. 재연결은 `.mcp.json`에 현재 저장된 상태로 서버를 재시작하지만, 이 세션은 실행 시 신뢰된 바이트 기준으로 승인되었습니다; 변경된 항목을 시작하면 승인 결정이 본 적 없는 서버가 실행됩니다. 변경을 적용하려면 세션을 재시작하세요; 그것이 유일한 적용 경로입니다.",
    'cmd.mcp-auth.reconnect.error' => '시작 실패: {error}',
    'cmd.mcp-auth.reconnect.heading' => '**MCP 서버 재연결됨**',
    'cmd.mcp-auth.reconnect.no-client' => '이 세션에 MCP 클라이언트 없음 — 재연결할 대상이 없습니다 (실행 시 `.mcp.json`이 신뢰되지 않았습니다).',
    'cmd.mcp-auth.reconnect.none' => '이 세션에 서버가 시작되지 않음',
    'cmd.mcp-auth.reconnect.refused' => '! `{server}`이(가) 승인 단계에서 거부됨 (신뢰 핀 불일치 또는 알 수 없는 항목).',
    'cmd.mcp-auth.reconnect.state.down' => '중지',
