    'cmd.mcp-auth.reconnect.state.up' => '실행 중',
    'cmd.mcp-auth.reconnect.tool-drift' => '{now}개 도구 제공; 이 세션은 {was}개로 구성됨 — 세션 중 모델 노출 목록은 재파생되지 않으므로, 새 세션을 시작하여 적용하세요',
    'cmd.mcp-auth.reconnect.unknown' => '이 세션에 `.mcp.json`의 실행 다이제스트가 기록되지 않아, 재연결 시 설정이 실행 시 바이트를 그대로 유지하는지 증명할 수 없습니다 — 거부됨, 재시작이 유일한 적용 경로입니다.',
    'cmd.mcp-auth.removed' => '✓ `{server}`의 자격 증명 제거됨',
    'cmd.mcp-auth.status.active' => '● 활성',
