    'cmd.mcp-auth.status.expiring' => '● 곧 만료',
    'cmd.mcp-auth.status.none' => '○ 자격 증명 없음',
    'cmd.mcp-auth.undiscovered' => "! `{server}`의 OAuth 엔드포인트를 찾을 수 없습니다.\n\n명시적으로 입력하세요:\n  `mcp auth add {server}` *<registration-url>* *<token-url>*\n\n발견할 항목이 없다는 것은 보통 등록할 항목이 없다는 뜻입니다:\n로그인이 필요 없는 서버는 .mcp.json에 \"url\"만\n선언하면 바로 실행됩니다 (docs/MCP.md, \"{section}\").",
    'cmd.mcp-auth.unknown' => '알 수 없는 하위 명령 \'{sub}\'. 사용 가능: list, add, remove, login, reconnect, enable, disable',
    'cmd.mcp-auth.usage' => "사용법:\n  mcp auth list                    — 등록된 서버 목록 표시\n  mcp auth add <server> [reg-url] [token-url]  — 서버의 OAuth 자격 증명 저장\n  mcp auth remove <server>         — 서버의 자격 증명 제거\n  mcp auth login <server>          — 대화형 로그인 셸 명령 출력\n  /mcp reconnect                   — 선언된 서버 재시작 (.mcp.json이 실행 시와 일치할 때만)\n  /mcp enable <server> [--persist]   — 이 세션의 선언된 서버 거부 해제\n  /mcp disable <server> [--persist]  — 이 세션에서 선언된 서버 호출 거부",
