    'cmd.review.bad-ref' => '리뷰: `{ref}`은 git 리비전이 아닙니다 — `/review`은 HEAD, 브랜치 또는 태그 이름, 커밋 sha, `HEAD@{1}` 또는 `@{u}` 같은 reflog 주소, `base..HEAD` 또는 `base...HEAD` 같은 범위(범위의 양쪽 모두 해석 가능해야 함) 중 하나의 tree-ish를 받습니다.',
