    'sandbox.hook.not_run' => '실행 안 됨: 훅 `{hook}`이(가) sandboxScope에 의해 `{mode}` 샌드박스로 스코프되었지만, 이 호스트에서 {name} 샌드박스를 시작할 수 없습니다 ({reason}). 샌드박스 여부와 관계없이 아무것도 실행되지 않았습니다. 사용자에게 알려주세요: {name}을(를) 수정 ({remedy})하거나 bashSandbox를 "off"로 설정할 수 있습니다.',
    'sandbox.lsp.not_started' => '시작 안 됨: `{language}` 언어 서버 ({command})이(가) sandboxScope에 의해 `{mode}` 샌드박스로 스코프되었지만, 이 호스트에서 {name} 샌드박스를 시작할 수 없습니다 ({reason}). 격리 여부와 관계없이 아무것도 시작되지 않았습니다. 사용자에게 알려주세요: {name}을(를) 수정 ({remedy})하거나, bashSandbox를 "off"로 설정하거나, 해당 서버의 `lsp` 항목에 `"sandbox": false`를 지정하여 예외 처리할 수 있습니다.',
    'sandbox.mcp.not_started' => '시작 안 됨: MCP 서버 `{server}`이(가) sandboxScope에 의해 `{mode}` 샌드박스로 스코프되었지만, 이 호스트에서 {name} 샌드박스를 시작할 수 없습니다 ({reason}). 격리 여부와 관계없이 아무것도 시작되지 않았습니다. 사용자에게 알려주세요: {name}을(를) 수정 ({remedy})하거나, bashSandbox를 "off"로 설정하거나, 사용자 티어 항목에 `"sandbox": false`를 지정하여 예외 처리할 수 있습니다.',
    'sandbox.mcp.opt_out_ignored' => '무시됨: MCP 서버 {servers}의 `"sandbox": false` 옵트아웃이 사용자 설정 파일에서 오지 않았습니다 — 사용자 티어만 stdio 서버를 sandboxScope 격리에서 예외 처리할 수 있습니다. 서버가 스코프된 대로 격리됩니다.',
    'sandbox.runner.skipped' => '건너뜀: {scope} 실행이 sandboxScope에 의해 `{mode}` 샌드박스로 스코프되었지만, 이 호스트에서 {name} 샌드박스를 시작할 수 없습니다 ({reason}). 샌드박스 여부와 관계없이 아무것도 실행되지 않았습니다. 사용자에게 알려주세요: {name}을(를) 수정 ({remedy})하거나 bashSandbox를 "off"로 설정할 수 있습니다.',
