    'send.session.subagent' => '서브 에이전트는 다른 세션에 메시지를 보낼 수 없습니다; `session:` 대상은 세션 자체의 에이전트용입니다 — 부모에게 메시지를 보내거나, 보고하여 부모가 대화를 대신하도록 하세요.',
