    'chat.turn.output_limit' => '제공자가 출력 한도에서 이 응답을 중단했으므로 위 텍스트가 중간에 끊길 수 있습니다. 더 긴 단일 응답을 위해 ~/.candy-code/config.json의 `maxOutputTokens`를 높이거나, 다음 메시지에서 나머지를 요청하세요.',
    'chat.turn.steps_exhausted' => '이 턴이 작업 완료 전에 모든 도구 단계를 소진했으므로, 위 응답은 중단된 위치를 설명합니다 — 완료된 것과 남은 것 — 최종 답변이 아닙니다. `continue`를 입력하여 이어서 진행하거나, 더 긴 에이전트 턴을 위해 상한을 높이세요 — 실행 시 --max-turns 플래그가 ~/.candy-code/config.json의 `maxToolSteps` 설정보다 우선하므로, 현재 적용 중인 쪽을 높이세요.',
    'chat.turn.unpriced_model' => '이 앱에 모델 `{model}`의 가격이 등록되어 있지 않아, 이 턴은 $0.00으로 과금되었습니다 — 무료 호출이 아닌 하한값입니다. 요율이 설정되기 전까지 총 지출과 지출 상한이 과소 집계됩니다. ~/.candy-code/config.json의 `modelPrices` 아래에 요율을 선언하세요 (1M 토큰당 USD, 키 `input`과 `output`).',
