    'host.bg.stop_usage' => '사용법: /bg stop <session-id>',
    'host.bg.usage' => '사용법: /bg <task>',
    'host.command_shell.bundle_refused' => '[!`{command}`이(가) 실행되지 않았습니다: /{name}은(는) 타인이 패키징한 플러그인 번들에서 온 것입니다. 번들 항목은 어떤 티어로 설치되었든 셸 형태가 거부됩니다 — 로컬 권한 부여로 해제할 수 없으며, 출처별 옵트인이 예정된 후속 작업입니다 — 명령의 나머지는 전송되었습니다.]',
    'host.command_shell.mcp_refused' => '[!`{command}`이(가) 실행되지 않았습니다: /{name}은(는) 서버에서 가져온 MCP 프롬프트로, 네트워크를 통해 도착한 텍스트입니다. 가져온 본문은 이 프로젝트가 신뢰하는 것과 무관하게 셸 형태가 거부됩니다 — 로컬 권한 부여로 해제할 수 없으며, 출처별 옵트인이 예정된 후속 작업입니다 — 프롬프트의 나머지는 전송되었습니다.]',
    'host.loop.not_configured' => '이 세션에 스케줄이 설정되지 않음 — /loop에 실행할 시계가 없습니다. 일반 `candy-code` 실행에는 항상 하나 포함되어 있으며, 호스트 통합 빌드는 이를 제공해야 합니다.',
    'host.loop.usage' => '사용법: /loop <interval> <prompt> — 간격 예: 90s, 15m, 2h, 1d (최소 10s). 루프는 이 프로세스에 존재합니다; /schedules로 나열, /schedules delete로 종료.',
    'host.loop.bad_interval' => '간격 형식이 아닙니다: {interval}. 초 단위(60) 또는 접미사를 사용하세요: 90s, 15m, 2h, 1d.',
    'host.loop.registered' => '루프 {name}: 매 {every} — `{prompt}`이(가) 여기서 턴으로 큐됩니다(첫 실행은 한 간격 후). 프로세스 종료 시 또는 /schedules delete {name}으로 종료됩니다.',
