    'host.output_style.cleared' => '현재 활성 출력 스타일이 없습니다 — 다음 턴부터 스타일 규칙집 없이 프롬프트가 실행됩니다.',
    'host.output_style.column_source' => '출처',
    'host.output_style.column_state' => '상태',
    'host.output_style.column_style' => '스타일',
    'host.output_style.empty' => "출력 스타일이 없습니다.\n스타일은 ~/.candy-code/styles/ (또는 프로젝트 내 .candy-code/styles/)에 있는 마크다운 파일 하나이며,\n파일명으로 지정됩니다: terse.md는 /output-style terse로 선택합니다.",
    'host.output_style.footer' => "/output-style <name>으로 스타일 하나를 선택합니다; 한 번에 정확히 하나만 적용되며,\n전환 시 이전 스타일이 해제됩니다. /output-style off로 슬롯을 비웁니다. `off`는 예약어입니다 —\n예약어 — off.md라는 이름의 파일은 선택할 수 없습니다. 해당 스타일은 ...에 의해 비활성화됨\n자체 frontmatter (`enabled: false`)는 이름과 무관하게 프롬프트에 포함되지 않습니다.",
    'host.output_style.heading' => '출력 스타일 (세션 전용 — 여기에 있는 것은 설정에 기록되지 않음):',
