    'host.schedules.usage' => '사용법: /schedules [list] | add <name> <interval> <prompt> [--mode <mode>] [--provider <name>] [--heartbeat] | enable <name> | disable <name> | delete <name>. 항목은 ~/.candy-code/schedules.json에 저장됩니다; /schedules add는 Schedule 도구의 팩토리 경계를 통해 하나를 생성하며, /loop는 일시적 항목을 등록합니다.',
    'host.schedules.none' => '스케줄이 없습니다. /schedules add <name> <interval> <prompt>로 Schedule 도구와 동일한 경계를 통해 생성하거나, ~/.candy-code/schedules.json에 항목을 작성하세요 (`name`, `every` 초 단위, `prompt`, `root` — 실행될 프로젝트 디렉터리; 선택 `provider`, `permissionMode` (bypass 계열 표기는 거부; 생략 시 비대화형 하한 적용), `enabled`, `timeoutSeconds`, `kind` (`task` 응답, `heartbeat`는 무응답 가능)), 또는 이 세션에 /loop로 등록하세요. docs/SCHEDULES.md가 형식 문서입니다.',
