    'host.schedules.added' => '스케줄 {name}: 매 {every} — `{prompt}`이(가) 이 프로젝트에서 관리형 백그라운드 실행으로 트리거됩니다(첫 실행은 한 간격 후, 다음 {next}). Schedule 도구의 팩토리로 생성: 모드는 생성 시 확정, 프로젝트별 모델 상한에 산정, 이 루트에 바인딩. `/schedules delete {name}`으로 제거.',
