    'host.compact.summarising.other' => '이전 {count}개 교환을 모델로 요약 중 — 도착하면 트랜스크립트가 압축됩니다.',
    'host.compact.thrash' => '컨텍스트 압축이 {times}회 연속 실행되었지만 매번 트랜스크립트가 한도를 초과하여 이 프롬프트는 전송되지 않았고 추가 압축도 시도되지 않았습니다. 재작성본이 전체를 유지하는 최근 교환이 한도를 초과하는 항목입니다 — 가장 큰 것을 줄이세요 (도구 출력이 대부분입니다). /rewind 또는 /clear로 다시 시작하거나, /model로 더 큰 컨텍스트 창을 설정하세요.',
