    'host.compact.truncated.other' => '{count}개 메시지가 단독으로 {tier}에 도달하여 턴 거부가 아닌 컨텍스트 창에 맞게 잘렸습니다: 현재 ~{tokens}개 추정 토큰, {limit}토큰 컨텍스트 창 대비. 모델에 전송되는 텍스트에는 각각 잘린 위치에 마커가 있습니다. 전체 원본은 트랜스크립트에 남아 모델에게 숨겨집니다.',
