    'host.spend.usage' => '사용법: /budget <금액>으로 이 세션 지출 상한 설정 (예: /budget 5 또는 /budget $2.50), /budget off로 해제, /budget 단독으로 현재 상태 확인. 금액은 0보다 큰 실수여야 합니다 — 상한 0과 상한 없음은 반대 요청이므로 `0`은 추측하지 않고 거부되며, 표현 불가능한 값 (`1e309`, 무한대)도 절대 트리거되지 않는 상한으로 수락하지 않고 거부됩니다.',
