    'host.turn.empty_custom_command' => '{draft}는(은) 템플릿이 빈 결과로 확장된 명령 파일입니다 — 대부분 본문이 $ARGUMENTS 또는 $1뿐인데 인자 없이 호출된 경우입니다. 아무것도 전송되지 않았습니다: 빈 프롬프트는 턴 비용만 발생하고 모델에 아무것도 전달하지 않습니다. 인자를 전달하거나, 파일에 독립적으로 성립하는 본문을 작성하세요.',
