    // --- fix-app-launch 2026-10-14 ---
    'appLaunch.doctor.mbstring_missing' => '누락 — 프레임 폭 계산(mb_*) 실행 불가; ext-mbstring 포함 PHP 재설치',
    'appLaunch.doctor.intl_missing' => '누락 — grapheme/IntlChar 폭 계산 실행 불가; ext-intl 포함 PHP 재설치',
    'appLaunch.notice.policy_changed' => '⚠ 이전 실행 이후 config.json 또는 hooks.yaml이 변경되었습니다. 새 프로젝트 훅은 이번 실행 동안 격리됩니다 — ~/.candy-code/config.json과 hooks.yaml을 검토하면 적용됩니다',
    'appLaunch.notice.project_policy_changed' => '⚠ 신뢰된 프로젝트의 hooks.yaml에 이전 실행에서 본 적 없는 항목이 있습니다. 새 프로젝트 훅은 이번 실행 동안 격리됩니다 — 해당 저장소의 .candy-code/hooks.yaml을 검토하면 적용됩니다',
    'appLaunch.notice.bypass_mode' => '⚠ 권한 모드가 bypass-permissions입니다: 모든 도구 호출이 프롬프트 없이 실행됩니다. /permissions (TUI), --permission-mode로 변경하거나 ~/.candy-code/config.json에서 다른 권한 모드를 설정하세요',
    // C-SEC-7.a: `-p` now defaults to the ASKING mode, so an unattended scripted
    // run that named no mode starts refusing — the launch says so once, and names
    // the one-flag fix. No trailing period — STDERR_LINE_FORMAT adds one
    // (LaunchNoticeOwnPeriodTest).
    'appLaunch.notice.headless_default' => 'ℹ -p는 권한 모드 default로 시작합니다: 무인 실행은 확인이 필요한 모든 도구 호출을 거부합니다. 스크립트 실행 시 --permission-mode (bypass-permissions는 모든 것 실행)를 지정하세요',
    // C-SEC-7.e (owner ruling t212, option 3): the implicit autoReview default
    // announces once per session the first time it engages — de-duped by message
    // identity in the launch-notices store, like the bypass banner. Names the
    // opt-out and owns up to the money. No trailing period — STDERR_LINE_FORMAT
    // adds one (LaunchNoticeOwnPeriodTest).
    'appLaunch.notice.auto_review_default' => '⚠ autoReview가 이번 실행에서 기본적으로 켜져 있습니다: 플래그된 auto 모드 호출은 타이틀 모델이 검토하며, 모든 검토는 유료 모델 호출입니다. ~/.candy-code/config.json에서 autoReview를 false로 설정하여 비활성화하세요',
    // C-SEC-6.b: names the file, what it added, and what could not be honoured.
    // No trailing period — STDERR_LINE_FORMAT adds one (LaunchNoticeOwnPeriodTest).
    'appLaunch.notice.project_narrowing_rules' => '⚠ {file}이 이번 실행의 권한을 축소했습니다: {count}개 deny/ask 규칙이 먼저 로드됨, {dropped}개 allow 규칙 폐기 — 프로젝트 파일은 allow를 부여할 수 없음',
    'appLaunch.notice.restricted' => '⚠ --restricted: 이번 실행은 코드 실행 도구 없이 동작합니다 — Bash, PtyRun, Task, Workflow, ShellStop, mcp_call이 모든 모델 노출 세트에서 제외됨; 파일 도구는 경로 제한 하에 유지되며 /permissions로 제거된 도구를 복원할 수 없음',
    'appLaunch.notice.safe_mode' => '⚠ --safe-mode: 이번 실행에서 신뢰된 프로젝트 루트, 번들, 외부 스킬, 명령, 에이전트가 모두 무시됩니다 — 아무것도 신뢰된 적 없는 것처럼 동작합니다',

    // --- fix-w2-chat 2026-10-14 ---
    'chat.launch.echo_backend' => '프로바이더가 설정되지 않아 이 세션은 내장 오프라인 에코 백엔드로 실행됩니다 — 응답은 로컬에서 에코되며 모델이 호출되지 않습니다. `candy-code doctor`를 실행하여 프로바이더 요구 사항을 확인하고, 설정 후 Ctrl+P로 모델을 전환하세요.',
