    // --- C-EXT-1 (Claude Code hook dialect) 2026-10-27 ---
    'hooks.notice.advisory' => '⚠ `async` Claude Code 훅 `{hook}`이(가) {code}로 종료되었습니다. `async` 훅은 도구 호출을 차단하는 것이 아니라 관찰을 요청하므로 차단 권한이 없으며 호출이 진행되었습니다. 메시지: {reason}',
    'hooks.notice.claude_dialect' => '⚠ Claude Code 훅 `{hook}`이(가) {code}로 종료되었습니다. Claude Code는 이를 차단이 아닌 비차단 불만으로 해석하므로 도구 호출이 진행되었습니다. 메시지: {reason}',
