    // --- C-EXT-6.c (type: http hooks) 2026-10-30 ---
    // Every row names the hook and scheme://host only: never a path, a query,
    // or any header value, so an Authorization cannot ride out of the process
    // inside its own refusal.
    'hooks.http.deny_bad_url' => 'HTTP 훅 `{hook}`에 사용할 수 없는 URL이 설정되어 있습니다 ({reason}); 표시된 대상은 {target}입니다. 어디로 가는지 명시할 수 없는 훅은 이 호출을 승인하지 않았습니다.',
    'hooks.http.deny_scheme' => 'HTTP 훅 `{hook}`의 대상 {target}은(는) http 또는 https URL이 아닙니다. candy-code는 이 두 스킴으로만 훅에 연결하며, 검증되지 않은 전송 경로로 실행하는 대신 호출을 거부합니다.',
    'hooks.http.deny_credentials' => 'HTTP 훅 `{hook}`의 URL에 자격 증명이 포함되어 있습니다 ({target}). URL에 비밀번호를 쓰면 로그와 프록시에 남으므로 거부됩니다; 대신 값이 `allowedEnvVars` 이름을 읽는 헤더로 전송하세요.',
    'hooks.http.deny_blocked_target' => 'HTTP 훅 `{hook}`에 문의할 수 없습니다: {reason} ({target}). 사설 및 링크 로컬 주소는 아웃바운드 fetch와 동일한 규칙으로 거부되며, 도달하지 못한 가드는 이 호출을 승인하지 않았습니다.',
    'hooks.http.deny_unanswered' => 'HTTP 훅 `{hook}`이 응답하지 않았습니다 ({reason}); 대상은 {target}이었습니다. 도달할 수 없는 훅은 이 호출을 승인하지 않았으므로 거부됩니다.',
    'hooks.http.deny_header_injection' => 'HTTP 훅 `{hook}`이 `{field}` 헤더를 전송할 수 없습니다: 이름 또는 값에 제어 문자가 포함되어 있어 헤더 값이 아닌 요청 프레이밍으로 간주됩니다. {target}으로 아무것도 전송되지 않았으며 호출이 거부됩니다.',
    'hooks.http.notice_unanswered' => '⚠ HTTP 훅 `{hook}`이 응답하지 않았습니다 ({reason}), 호출을 게이트할 수 없었습니다. {target}에서 요청되었습니다.',
    'hooks.http.reason_unreachable' => '연결 또는 요청이 자체 훅 타임아웃 내에서 만료됨',
    'hooks.http.reason_oversized' => '응답이 {bytes}바이트를 초과하여 불완전하게 종료됨',
    'hooks.http.reason_no_status' => '응답에 HTTP 상태 줄이 없음',
    'hooks.http.reason_redirect' => '리디렉트 발생, 훅 호출은 리디렉트를 따르지 않음',
    'hooks.http.reason_status' => '응답이 2xx 상태가 아님',


    // --- C-EXT-6.d (type: prompt hooks) 2026-10-31 ---
    // Nothing was dialled and nothing was spent when these fire, so no row
    // carries a {target}: the hook either has no backend to be asked on, or
    // the answer it got is not a verdict.
    'hooks.prompt.deny_unanswered' => '프롬프트 훅 `{hook}`이 응답하지 않았습니다 ({reason}). 판정이 반환되지 않은 훅은 이 호출을 승인하지 않은 것이므로 거부됩니다.',
    'hooks.prompt.notice_unanswered' => '⚠ 프롬프트 훅 `{hook}`이 응답하지 않았습니다 ({reason}), 호출을 게이트할 수 없었습니다.',
    'hooks.prompt.reason_call_failed' => '모델에 질문할 수 없음',
    'hooks.prompt.reason_empty_verdict' => '프롬프트 훅 `{hook}`이 이유 없이 이 호출을 거부했습니다.',
    'hooks.prompt.reason_no_backend' => '이 실행에는 질문할 제목 백엔드가 없음',
    'hooks.prompt.reason_no_prompt' => '항목에 질문할 프롬프트가 비어 있음',
    'hooks.prompt.reason_unparseable' => '응답이 필수인 부울 `ok`를 포함한 단일 JSON 객체가 아님',

    // --- settings help (W3-B i18n migration) ---
    'settings.advisorModel.help' => '`Advisor` 도구가 두 번째 의견을 구하는 모델; 미설정(기본값)이면 도구를 제공하지 않음 (저가 모델 폴백 없음: 직접 선택한 모델이 핵심).',
    'settings.allowedTools.help' => '도구 이름 또는 글롭 화이트리스트; 미설정이면 모든 도구 제공.',
    'settings.attribution.help' => '{"commit": "…", "pr": "…"}: git 가이드가 요구하는 트레일러 및 PR 줄.',
    'settings.autoCommit.help' => 'off, turn(턴당 커밋 1개, 메시지는 제목 모델에서 생성) 또는 edit(Write/Edit마다 1개); /undo로 되돌림.',
    // C-SEC-7.e (owner ruling t212, option 3): the help states the implicit
    // default, the once-per-session announce, and the paid-call fact.
    'settings.autoReview.help' => 'auto에서 안전 분류기가 플래그한 호출(보안 감지 제외, 항상 질문)은 제목 모델이 검토하여 허용, 질문 또는 거부합니다. 검토 가능한 모델이 있으면 기본적으로 켜지며, 해당 기본값을 활성화하는 실행은 한 번 알림; false로 설정하여 옵트아웃. 모든 검토는 유료 모델 호출입니다.',
    'settings.autoReviewModel.help' => 'auto 리뷰어가 실행하는 `provider/model`, 예: `openai/gpt-4.1-mini`; 비우면 제목 모델. 빌드할 수 없는 제공자는 리뷰어를 끄고 실행 경고 표시.',
    'settings.autoReviewScope.help' => '`autoReview`가 리뷰어에게 보내는 내용: `shell`(기본)은 패턴 목록을 통과한 모든 비읽기 전용 셸 명령; `writes`는 `Edit`, `Write`, `ApplyPatch`, `WebFetch`도 검토하며 쓰기 도구의 대기 중 diff 포함; `all`은 목록을 통과한 모든 호출 검토. 다른 표기는 `shell`로 동작. 모든 검토는 유료 모델 호출.',
    'settings.autoTest.help' => '파일을 편집한 턴 후 `testCommand` 실행; 실패 시 출력을 모델에 반환, 턴당 최대 3회.',
    'settings.bashInteractiveIdleSeconds.help' => '`interactive: true` Bash 실행이 키 입력 대기 중으로 중지되기 전 아무것도 출력하지 않을 수 있는 초 단위 시간.',
    'settings.bashMaxTimeoutSeconds.help' => 'Bash 명령이 요청할 수 있는 최대 `timeout`; 초과 값은 이 값으로 클램프.',
    'settings.bashSandbox.help' => 'Linux는 Bash를 bubblewrap 내부에서 실행; macOS는 `sandbox-exec`로 Seatbelt 프로필 내부에서 실행 — 작업 루트(`no-network`는 네트워크도 차단)에서만 쓰기 가능. `allowlist`(Linux)는 네트워크 아웃바운드를 실행의 egress 프록시를 통해 라우팅하며, `sandboxAllowedDomains`에 나열된 호스트만 허용: 기본 EMPTY 목록에서는 호스트를 나열할 때까지 `no-network`와 정확히 동일하게 동작하며, 나열 후에도 비HTTP 트래픽(ssh, 데이터베이스 포트)과 나열되지 않은 호스트는 실패. macOS에서 `allowlist`는 `no-network`로 강제 적용. 감옥 시작 불가 시 명령 거부; 인식되지 않는 값은 `no-network`, 절대 `off`가 아님.',
    'settings.bashSandboxNestedUserns.help' => '`true`로 설정하면 샌드박스 `Bash` 명령이 자체 사용자 네임스페이스를 생성할 수 있음 — rootless podman, buildah, Chromium 샌드박스에 필요. 기본값 `false`는 bubblewrap을 `--unshare-user --disable-userns`로 실행하여 마운트 감옥에서 빠져나가는 일반 경로를 차단; 해당 플래그를 지원하지 않는 오래된 bubblewrap 호스트에서는 일반 세트를 실행하고 자체 설명에 표시.',
    'settings.bashTimeoutSeconds.help' => '모델이 `timeout`을 전달하지 않을 때 Bash 명령이 실행될 수 있는 초 단위 시간; Bash 상한을 초과하지 않음.',
    'settings.chatToolTimeoutSeconds.help' => '채트 네이티브(`command` 제공자) 경로가 포크하는 도구 호출 배치의 월클록 예산; 늦은 작업은 종료.',
    'settings.claudeMcpArgs.help' => '해당 바이너리의 인자; 미설정 시 트랜스포트 기본값 사용.',
    'settings.claudeMcpBinary.help' => 'claude-mcp 트랜스포트가 스폰할 수 있는 `claude` 바이너리의 절대 경로.',
    'settings.claudeMcpEnv.help' => '해당 바이너리에 전달되는 리터럴 환경 변수.',
    'settings.compaction.autoPercent.help' => '프롬프트 전송 전 오래된 교환이 자동으로 압축되는 윈도우 점유율.',
    'settings.compaction.autoTokens.help' => '자동 티어 및 턴 내 단계 예산의 절대 상한. 0이면 상한 해제.',
    'settings.compaction.blockPercent.help' => '이 점유율을 초과하면 공간을 확보할 때까지 프롬프트가 거부되는 차단 티어; 거부하는 유일한 티어.',
    'settings.compaction.blockTokens.help' => '차단 티어의 절대 상한; 기본값 미설정. 설정하면 상한이 프롬프트를 거부할 수 있음.',
    'settings.compaction.idleAuto.help' => '유휴 중 자동 티어 기계를 사용하여(지출 상한 및 스래시 브레이커 적용) 다음 프롬프트를 기다리지 않고 유휴 초과 티어 세션을 압축. off: 절대 안 함; hour: compaction.idleOfferSeconds 윈도우 전체 후; cacheTtl: 제공자 프롬프트 캐시 만료 직전 — 제공자가 캐시 브레이크포인트를 표시하면 1시간, 서버 측 캐시는 약 5분, 캐시 없음 보고 시 절대 안 함 — 히스토리가 자동 티어보다 한 단계 아래 바닥을 초과하면, 다음 프롬프트가 전체 대화를 캐시 없이 프리필하게 되므로; 60초 틱에서 5분 캐시는 약 4분 유휴 시 압축. 백그라운드 제공자 호출 비용 발생; compaction.idleOfferSeconds가 0 이상이어야 함. bool도 읽기 가능: true는 hour, false는 off.',
    'settings.compaction.idleOfferSeconds.help' => '전체 컨텍스트 윈도우를 초과한 세션이 이 시간 동안 미접촉이면 프롬프트 전송 대신 /compact를 제안. 0이면 제안 안 함.',
    'settings.compaction.keepRecent.help' => '압축 시 전체를 유지하는 가장 최근 사용자/어시스턴트 교환 수.',
    'settings.compaction.mode.help' => 'llm: 요약 모델이 요약을 작성(휴리스틱은 폴백); heuristic: 로컬 한 줄 요약, 모델 호출 없음; off: 자체 압축 없음, /compact는 계속 작동하며 차단 티어는 계속 거부.',
    'settings.compaction.modelTokenCaps.help' => '{"<model>" 또는 "<provider>/<model>": {"reminderTokens", "autoTokens", "blockTokens"}} 세 상한을 오버라이드; 0이면 해당 상한 해제.',
    'settings.compaction.refillLimit.help' => '연속 자동 압축이 해당 티어를 바로 초과하여 프롬프트 미전송 상태로 돌아올 수 있는 횟수; 초과 시 다음 프롬프트는 압축 대신 거부.',
    'settings.compaction.reminderPercent.help' => '"압축 고려" 리마인더와 사전 백그라운드 요약이 시작되는 윈도우 점유율; 자동 티어 미만.',
    'settings.compaction.reminderTokens.help' => '리마인더 티어의 절대 상한: min(백분율, 이 값)에서 발동. 0이면 상한 해제.',
    'settings.compaction.summaryAssistantChars.help' => '이보다 긴 어시스턴트 응답은 휴리스틱 요약 줄에서 "[exchanged information]"로 대체.',
    'settings.compaction.summaryUserChars.help' => '휴리스틱 요약 줄이 유지하는 사용자 메시지의 문자 수.',
    'settings.compaction.toolOutputChars.help' => '요약 모델이 보는 압축된 교환의 어시스턴트 부분의 문자 수.',
    'settings.connectTimeoutSeconds.help' => '제공자 호스트 연결(DNS, TCP, TLS)의 상한; 요청 타임아웃이 아님.',
    'settings.contextPruning.compress.help' => 'manual은 /compress로 시작하는 턴에서만 Compress를 제안, 호출 1회; auto는 모델이 정리할 수 있는 모든 턴에서 제안.',
    'settings.contextPruning.iterationNudgeThreshold.help' => '마지막 프롬프트 이후 긴 도구 루프가 정리를 리마인드받기까지의 도구 결과 수.',
    'settings.contextPruning.maxContextTokens.help' => '이보다 큰 컨텍스트 크기에서 최신 행이 더 강한 "지금 정리" 리마인더를 포함.',
    'settings.contextPruning.minContextTokens.help' => '이보다 작은 컨텍스트 크기에서는 모델이 정리를 리마인드받지 않음; 하드 리마인더 크기를 초과할 수 없음.',
    'settings.contextPruning.mode.help' => 'auto는 각 턴 시작 시 대체된 행을 정리; manual은 /sweep에서만; off는 ref 태그를 표시하지 않음. /pruning이 세션별로 오버라이드.',
    'settings.contextPruning.nudgeFrequency.help' => '리마인더가 마지막 후 대기하는 새 행 수, 매 단계 반복 방지.',
    'settings.contextWindow.help' => '토큰 윈도우 오버라이드: 제공자 모델의 카운트 또는 {"<model>": tokens}.',
    'settings.debug.commands.help' => '거부된 각 사용자 정의 명령 디렉터리 또는 파일을 stderr에 출력, 실행의 한 줄 카운트만 표시하지 않음.',
    'settings.debug.rules.help' => '거부된 각 규칙 디렉터리 또는 파일을 stderr에 출력.',
    'settings.debug.skills.help' => '건너뛴 각 스킬 파일과 거부된 스킬 디렉터리를 stderr에 출력, 실행의 한 줄 카운트만 표시하지 않음.',
    'settings.debug.stream.help' => '임베더의 스트리밍 싱크가 턴 중 실패할 때 "onToken observer threw, detaching it" 줄을 stderr에 출력.',
    'settings.diffPreviewRows.help' => '나머지가 요약되기 전 트랜스크립트에 표시되는 Edit 또는 Write diff의 행 수.',
    'settings.diffStyle.help' => '트랜스크립트의 diff 레이아웃: `auto`는 넓은 터미널(120열 이상)에서 헝크를 나란히, 그 외에는 통합 표시, `unified`는 항상 한 열, `split`은 항상 두 열. diff 본문은 두 레이아웃 모두 토큰별 색상 적용; `+`/`-` 마커 열은 색상 유지.',
    'settings.disabledMcpServers.help' => '`.mcp.json` 서버 이름 또는 글롭(`untrusted_*`)으로, 메인 에이전트와 모든 서브 에이전트에서 절대 시작, 나열 또는 호출되지 않음.',
    'settings.disabledRules.help' => '첫 턴부터 프롬프트에 포함되지 않는 사용자 티어 규칙 팩.',
    'settings.disabledSkills.help' => '발견에서 제거된 스킬; enabledSkills보다 우선.',
    'settings.disabledTools.help' => '모델 대상 도구 세트에서 제거된 도구 이름 또는 글롭.',
    'settings.doubleEscSeconds.help' => '실행 중인 턴을 취소하기 위해 두 번째 Esc가 첫 번째 후 따라야 하는 최대 시간.',
    'settings.embeddingModel.help' => '턴별 메모리 회상의 임베딩 모델; 미설정이면 키워드만으로 노트 순위 매김.',
    'settings.enabledSkills.help' => '전체 본문이 매 턴 시스템 프롬프트에 포함되는 스킬.',
    'settings.env.diffMaxBytes.help' => '주석과 함께 잘리기 전 각 git diff 섹션이 유지하는 바이트 수.',
    'settings.env.gitDiffAfterWrites.help' => '파일을 쓴 단계 후 스테이징 및 언스테이징 git diff를 턴 컨텍스트에 표시.',
    'settings.expandToolOutput.help' => '완료된 각 도구 호출의 출력을 트랜스크립트에 전체 표시; Ctrl+O 또는 클릭으로 개별 접기 가능.',
    'settings.extraBody.help' => '모든 `custom` 제공자 요청에 추가되는 최상위 요청 필드.',
    'settings.formatCommands.help' => '파일 확장자별 편집 후 포맷 명령({"php": "vendor/bin/php-cs-fixer fix {file}"}); 편집 후 린트 전에 실행되며 파일을 재작성. 기본값 off.',
    'settings.formatAuto.help' => '`formatCommands`에 해당 확장자 명령이 없을 때 내장 확장자 테이블(gofmt, rustfmt, ruff/black, shfmt, terraform fmt, 프로젝트의 node_modules prettier)로 편집된 파일을 포맷하도록 허용. 명시적 항목이 우선; 프로젝트는 여전히 `trustedProjectHooks` 필요. 기본값 off.',
    'settings.globMaxMatches.help' => 'Glob이 탐색을 중지하기 전 수집하는 경로 수; 출력 상한이 결과를 제한.',
    'settings.grepTimeoutSeconds.help' => 'Grep 검색이 종료되기 전 실행할 수 있는 초 단위 시간; 마감 전까지 찾은 히트는 부분 결과로 반환.',
    'settings.hooksDefaultTimeoutSeconds.help' => '`timeout:`이 없는 훅 항목이 거부로 계산되어 종료되기 전 실행할 수 있는 초 단위 시간.',
    'settings.includeGitInstructions.help' => 'Bash 도구의 일반 커밋 가이드가 시스템 프롬프트에 포함되는지 여부.',
    'settings.instructions.help' => '내용이 권위 있는 시스템 프롬프트 텍스트가 되는 파일의 글롭.',
    'settings.instructions.walkToRoot.help' => '옵트인: 가장 가까운 .git 마커 위쪽의 지시 파일도 읽되 홈 디렉터리는 포함하지 않음. 사용자 티어 전용; 모든 읽기는 포함 및 크기 예산 유지.',
    'settings.instructionsExclude.help' => '건너뛸 지시 파일의 글롭, 거부로 기록; 사용자 티어 전용 — 저장소는 운영자를 무음화할 수 없음. 체크아웃 내 파일은 체크아웃 상대 경로로 매칭; 그 밖의 조상 및 강제 파일은 절대 경로로 매칭, 따라서 `**/CLAUDE.local.md`는 조상 사본에도 도달.',
    'settings.keybindings.help' => '{"shell.palette": "Ctrl+B"}: 바인딩 ID에 추가 코드 바인딩(/keys 참조에서 이름 확인) — Ctrl+<key>, Alt+<key>, Shift+<key> 또는 단독 기능 키; 기본 코드도 계속 작동. 존재하나 사용 불가 시 실행 거부; 기본 바인딩의 키를 제거.',
    'settings.layout.help' => '도킹 패널 매니페스트; 패널 이동 시 셸이 기록.',
    'settings.lintCommands.help' => '파일 확장자별 편집 후 린트 명령({"php": "…", "js": false}); `php -l`은 내장.',
    'settings.lsp.help' => '{"php": {"command": "intelephense", "args": ["--stdio"]}}: 편집 후 진단, Read 아웃라인 및 Lsp 도구의 서버.',
    'settings.lspAutoDetect.help' => '프로젝트 지문이 지정한 언어 서버(composer.json → intelephense, package.json + tsconfig.json → typescript-language-server, pyproject.toml 또는 setup.py → pyright-langserver, go.mod → gopls, Cargo.toml → rust-analyzer)를 바이너리가 PATH에 있으면 시작; 수동 `lsp` 항목이 언어별 우선. 서버 시작은 해당 서버와 열린 트리의 빌드 코드를 실행하므로, 지문은 훅에 신뢰된 프로젝트에서만 서버를 시작; 비신뢰 루트는 시작하지 않고 건너뜀을 실행 통지에 기록.',
    'settings.maxCheckpoints.help' => '세션별 /rewind가 복귀할 수 있는 턴 체크포인트 수; 이보다 오래된 것은 정리.',
    'settings.maxCostUsd.help' => '실행의 제공자 보고 지출이 이 미국 달러에 도달하면 새 턴 거부; 미설정이면 상한 없음. /budget은 실행 중인 세션에만 변경.',
    'settings.maxOutputTokens.help' => '요청별 출력 상한; 미설정 시 오버라이드 없이 프로바이더 기본값 적용.',
    'settings.maxToolSteps.help' => '한 턴이 수행할 수 있는 프로바이더 호출 수; 미설정 시 엔진 기본값 유지.',
    'settings.mcp.enabled.help' => '신뢰된 프로젝트의 .mcp.json에 지정된 MCP 서버를 시작; off 시 시작하지 않고 각 화면에서 비활성으로 표시.',
    'settings.mcp.lazySchemaTokens.help' => '한 MCP 서버가 mcp_list/mcp_call로 위임하기 전에 광고할 수 있는 스키마 토큰 수; 0이면 위임하지 않음.',
    'settings.mcpResultCapBytes.help' => '한 MCP 도구의 응답이 모델에 전달할 수 있는 최대 바이트 수.',
    'settings.memory.autoConsolidate.help' => '완료된 턴의 영속적 사실을 메모리에 저장하고 압축 저널을 병합(드림 패스); 각 작업은 과금 호출.',
    'settings.memory.dreamIntervalSeconds.help' => '한 프로젝트의 두 드림 패스 간 최소 시간; 각 패스는 과금되는 읽기 전용 턴.',
    'settings.memory.dreamProposeSkills.help' => '드림 패스가 ~/.candy-code/skills-proposed에 초안 스킬을 제안하도록 허용; /skills로 수락하기 전까지 활성화되지 않음.',
    'settings.memory.entryMaxBytes.help' => '한 노트의 인덱스 행이 잘림 표시되기 전 최대 길이; 사용자 노트 예산 초과 시 해당 예산으로 하향.',
    'settings.memory.projectNoteMaxBytes.help' => '저장소의 .candy-code/memory/에 기록될 때 한 프로젝트 메모리 노트의 최대 크기.',
    'settings.memory.promptMaxBytes.help' => '메모리 인덱스 노트 행의 바이트 예산; 사용자 노트 예산은 이 안에 맞도록 하향.',
    'settings.memory.promptMaxEntries.help' => '프롬프트 메모리 인덱스가 나열하는 최대 노트 수(최신 우선); 사용자 노트 포함.',
    'settings.memory.userMaxBytes.help' => '총 예산 내 사용자 범위 행의 바이트 예산.',
    'settings.memory.userMaxEntries.help' => '노트 수 내에서 먼저 나열되는 크로스 프로젝트(사용자 범위) 노트의 최대 수.',
    'settings.modelPrices.help' => '모델별 1M 토큰당 USD({"input": …, "output": …}); 지출 합계 및 상한에 사용.',
    'settings.models.help' => '프로바이더별 실행 모델({"<provider>": "<model id>"}); 미설정 시 프로바이더 기본값 사용.',
    'settings.mouse.help' => '마우스 이벤트를 candy-code에 보고(클릭, 휠, 선택); off 시 터미널의 copy-on-select 기능 복원.',
    'settings.mouseClicks.help' => '클릭과 드래그가 대상에 작용; off 시 휠만 유지하고 클릭 무시.',
    'settings.notices.transcriptLimit.help' => '트랜스크립트 행으로 표시되는 시작 경고의 최대 수; 나머지는 "and N more" 행에 집계되고 stderr에 모두 기록.',
    'settings.notify.help' => 'off, bell (BEL) 또는 osc9(데스크톱 알림): 턴 종료 시 및 에이전트가 승인 대기 시 전송.',
    'settings.paletteMru.help' => '최근 사용된 팔레트 행의 기억 및 우선 순위 지정 수; 0이면 기억하지 않음.',
    'settings.parallelToolCalls.help' => '한 턴의 읽기 전용 도구 호출을 동시에 실행.',
    'settings.parallelToolDeadlineSeconds.help' => '동시 디스패치된 도구 호출 한 배치의 실제 시간 상한.',
    'settings.permissionMode.help' => '도구 호출 제어 방식. 프로젝트 파일에서 가져오지 않음.',
    'settings.permissionRules.help' => '각 도구 호출에 매칭되는 순서화된 허용 / 거부 / 확인 규칙. 신뢰된 프로젝트의 공유 settings.json이 거부 / 확인 항목을 추가할 수 있음 — 축소만 가능.',
    'settings.permissions.autoAllowReadOnly.help' => 'default 및 accept-edits에서 읽기 전용 명령만 포함된 Bash 행(ls, cat, grep, git log, …; 파일 리디렉션 없음, 치환 없음, cd는 프로젝트 내부만)을 확인 없이 실행. 프로젝트는 off만 가능.',
    'settings.permissions.autoStrikeLimit.help' => 'auto에서 한 카테고리의 차단된 호출이 이 수만큼 연속되면 다음 호출을 질문으로 전환.',
    'settings.permissions.autoTotalLimit.help' => 'auto 모드에서, 세션 중 이 횟수만큼 호출이 차단되면 이후 차단부터는 확인을 요청합니다.',
    'settings.pluginPaths.help' => '설치된 두 루트 외에 Claude 형식 플러그인 번들을 스캔하는 추가 디렉터리; 값은 번들 자체 또는 번들 컨테이너를 지정할 수 있음. 사용자 티어 전용 — 체크아웃은 자체 플러그인을 등록할 수 없음.',
    'settings.promptCache.keepWarm.help' => '유휴 구간당 허용 워밍 핑 수; 0(기본값)은 비활성화. 각 핑은 유휴 세션의 고정 접두어에 한 글자 응답을 요청하는 지시 행 하나를 붙여 재전송하므로, TTL 만료 전 제공자가 프롬프트 캐시를 갱신하여 다음 프롬프트가 전체 대화를 캐시 없이 프리필하지 않게 됩니다. cacheTtl 폴드가 하한 이하 또는 1시간 미만으로 감소한 경우에만, 폴드 워치가 이미 실행 중인 동일한 틱/알람에서 트리거 — 턴 중에는 절대 실행하지 않으며, 동시에 하나 이상, 구간당 이 수를 초과하지 않습니다. 이는 아무도 주시하지 않는 세션에 대한 과금 호출이며, 지출 상한은 여전히 적용됩니다. 해당 수치는 /usage의 `warm` 항목에 기록됩니다.',
    'settings.promptCache.help' => '`vertex` 및 `bedrock` 제공자가 프롬프트 캐시 분할 지점을 표시하는지 여부.',
    'settings.promptSuggestionHistory.help' => '프롬프트 제안 호출 시 최근 메시지(각각 2000자로 잘림)가 표시됩니다.',
    'settings.promptSuggestions.help' => '각 턴 후, 제목 모델에게 다음에 보낼 가능성이 높은 메시지를 요청하고 빈 입력 상자에 회색으로 표시합니다 (→ 수락).',
    'settings.provider.help' => '세션이 통신하는 LLM 제공자; 모든 프롬프트가 해당 호스트로 전송됩니다.',
    'settings.providerRetryAttempts.help' => '일시적 실패(네트워크, 5xx, 408, 429) 시 프로바이더 요청당 호출 횟수, 첫 호출 포함; 1이면 재시도 없음.',
    'settings.providerRetryBaseBackoffMs.help' => '실패한 프로바이더 호출의 첫 재시도 전 대기 시간; 이후 대기 시간이 매번 두 배로 증가.',
    'settings.providers.help' => '이름별 프로바이더 정의 ({"<name>": {"type": …, "baseUrl": …, "apiKey": …, "model": …}}); 각 항목은 해당 유형의 기본값 위에 중첩됩니다. 사용자 티어 전용: 프로젝트가 자격 증명의 전송 대상을 변경할 수 없습니다.',
    'settings.queueMode.help' => 'steer (에이전트가 다음 단계에서 읽음), followup (턴 종료 후 전송) 또는 interrupt (다음 단계에서 턴 중단 후 전송). Tab은 항상 대기열에 추가.',
    'settings.readMaxBytes.help' => '단일 Read 호출 상한; 아래 페이지는 읽기 시 일반적으로 반환되는 크기.',
    'settings.readPageBytes.help' => 'Read 페이지가 담을 수 있는 바이트 수(줄 번호 포함), `limit`으로 설정.',
    'settings.readPageLines.help' => 'Read 호출 시 `limit`을 지정하지 않은 경우 반환되는 줄 수.',
    'settings.reasoningEffort.help' => 'Thinking 티어는 해당 조합이 허용하는 곳에 전송됩니다: openai (o-series 및 gpt-5, -chat 빌드 제외), anthropic 및 vertex (claude-3-7 이상; vertex는 claude와 gemini 양쪽 모두에서 응답), gemini (2.5 이상), sglang (모든 요청에 전달), bedrock (claude ids, thinking 예산으로), codex 및 claude-code (명명된 티어를 CLI로 전달); 미설정 또는 인식 불가 시 요청하지 않습니다. `/effort`로 설정 및 해제합니다.',
    'settings.redactToolOutput.help' => '기본적으로 꺼짐: 확정된 도구 출력은 반환된 그대로 history와 sessions.db에 저장됩니다. 켜면, 모든 도구 결과가 확정된 후 memory와 `/share`를 보호하는 동일한 마스킹 처리기를 통과합니다 — 인식된 자격 증명이 저장 바이트와 이후 턴의 모델 재생 내용에서 `[REDACTED]`로 치환됩니다(도구 자체는 변경 없이 실행). 이미지, 문서, 사용량 필드는 그대로 통과. `/export`는 자체 마스킹을 추가하지 않습니다: 저장된 내용을 그대로 출력하므로, 이 설정을 켜기 전 저장된 내용은 원본 상태로 유지됩니다.',
    'settings.references.help' => '워크스페이스 외부의 읽기 전용 디렉터리 목록으로, Read, Grep, Glob, Ls도 열 수 있습니다: `[{"path": "…", "name": "…"}]`. 각 항목은 `<env>` 블록에 해당 위치의 내용을 제한된 맵으로 표시합니다. Write, Edit, Bash에 대한 워크스페이스 격리는 변경되지 않습니다 — 참조는 쓰기 범위를 확장하지 않습니다. 사용자 티어 전용: 체크아웃된 리포지토리는 읽기 루트를 추가할 수 없습니다. 경로가 없거나, 디렉터리가 아니거나, 세션 루트 내부에 있으면 시작 시 알림과 함께 거부됩니다.',
    'settings.repoMap.enabled.help' => '코드 위치 맵(패키지 및 PSR-4 소스 디렉토리)을 시스템 프롬프트에 포함하세요.',
    'settings.repoMap.maxBytes.help' => '저장소 맵 두 섹션 각각의 바이트 한도; 초과 항목은 나열 대신 개수만 집계.',
    'settings.requireReadBeforeWrite.help' => '켜짐: `Edit`, 기존 파일을 덮어쓰는 `Write`, 변경·이동·삭제를 수행하는 `ApplyPatch` 섹션은 모두 모델이 이 세션에서 해당 파일을 읽기 전까지 거부됩니다. 새 파일 생성은 차단되지 않습니다. 기본값: 꺼짐 — 모델이 읽은 파일은 어느 쪽이든 디스크 변경 규칙으로 보호됩니다.',
    'settings.resumeCostWarnUsd.help' => '오래된 재개 후 히스토리 재전송 비용이 캐시 없이 최소 이 금액 이상으로 추정되면 첫 프롬프트가 한 번 보류됩니다. Enter를 다시 눌러도 전송하거나 /compact를 먼저 실행하세요. 0이면 보류 비활성화.',
    'settings.sandboxAllowedDomains.help' => '`allowlist` 샌드박스가 접근할 수 있는 호스트: 일반 이름(`example.com`), `*.example.com` 와일드카드, `host:port` 표기(기본값: 없음). Linux에서 `bashSandbox`가 `allowlist`일 때만 사용; 목록이 비어 있으면 `allowlist`는 `no-network`와 정확히 동일하게 동작. 아웃바운드 프록시는 HTTP(S)만 허용 — 목록에 없는 모든 호스트는 403으로 응답하며, 비HTTP 트래픽(ssh, 데이터베이스 포트)은 실패. 잘못된 항목은 적용 시 무시됨: 오타는 허용 범위를 줄일 수만 있고 넓힐 수 없음. 사용자 티어 전용: 체크아웃된 저장소가 도착한 샌드박스에 구멍을 내면 안 됨. macOS에서는 `allowlist`를 `no-network`로 적용 — 루프백 포트 기능은 추적 중인 후속 작업.',
    'settings.sandboxScope.help' => '`bashSandbox` 격리에 참여하는 도구 경로 외부의 명령: `hooks`, `lint`, `format`, `test`, `lsp`, `mcp` (기본값: 없음). `bashSandbox`가 `off`가 아닌 동안에만 유효 — 이 목록은 누가 격리를 공유하는지 나타내며, 격리 존재 여부는 나타내지 않음. 인식되지 않은 항목은 EVERY 범위(가장 엄격, 인식되지 않은 `bashSandbox` 값과 동일)로 해석되며, 설정 감사에서 이를 명시. 격리를 시작할 수 없으면 격리 없이 실행하지 않고 작업을 거부: 스크립트 훅은 거부, lint·format·test는 사유와 함께 건너뜀, 격리된 LSP 또는 MCP stdio 서버는 시작되지 않음. `lsp` 항목과 사용자 티어 MCP 항목에는 서버별 `"sandbox": false` 옵트아웃이 있음; 프로젝트 티어 MCP 옵트아웃은 무시됨.',
    'settings.screenReader.help' => '스크린리더 사용자용 표시 방식. 켜면, 스크린리더가 낭독할 수 없는 장식을 제거합니다 — 에이전트 스피너가 정적 프레임으로 고정되고, 박스 그리기 프레임, 반전 영상 전용 메뉴 선택 등이 일반 텍스트와 청각 신호로 대체되며, 각 화면이 이 전환을 따릅니다. 끄면 평소처럼 채색된 터미널입니다. 사용자 고유의 접근성 설정으로, 초안함 vim 모드처럼: 체크아웃된 프로젝트가 변경할 수 없습니다. 저장 후 다음 읽기 시 적용 — 즉시, 재시작 불필요.',
    'settings.rules.standingMaxBytes.help' => '모든 프롬프트에 통째로 삽입되는 규칙 파일의 바이트 한도(프레임·이스케이프 적용); 초과 규칙은 한 줄 포인터로만 표시됩니다.',
    'settings.scrollWheelLines.help' => '휠 한 칸당 전사 한 줄 스크롤.',
    'settings.sd.apiKey.help' => 'Stable Diffusion 서버가 요구 시 전송하는 Bearer 키; 리터럴보다 `${VAR}` 자리표시자 형식 권장.',
    'settings.sd.baseUrl.help' => 'AUTOMATIC1111 호환 Stable Diffusion webui의 HTTP 기본 URL (`http://127.0.0.1:7860`); 프롬프트, 이미지, API 키가 모두 해당 주소로 전송됩니다.',
    'settings.sd.defaultModel.help' => '모델 ID 생성 요청 시작 접두사; 미설정 시 서버가 자체 선택합니다.',
    'settings.sd.presets.help' => '미디어 폼이 제공하는 명명된 매개변수 번들; 형식은 미디어 파이프라인 자체의 것, 설정 레이어에는 불투명.',
    'settings.sd.savePattern.help' => '저장 미디어 파일 이름 템플릿; `[date]`, `[time]`, `[seed]`, `[number]` 토큰은 저장 시점에 채워집니다.',
    'settings.sd.timeoutSeconds.help' => '초 - 생성 요청이 중단되기 전까지의 허용 시간; 약한 GPU에서 디퓨전은 보통 수 분 소요',
    'settings.secretEnvAllowlist.help' => '자격 증명 형태의 변수 이름(또는 glob)을 Bash, Grep 및 스크립트 훅이 여전히 상속',
    'settings.server.allowBypass.help' => '서버 세션이 bypass-permissions 또는 dont-ask 모드로 실행될 수 있는지 여부 (--allow-bypass와 동일).',
    'settings.server.allowedHosts.help' => '루프백 이름과 자체 주소 외에 서버가 응답하는 호스트 이름(또는 host:port), 예: 리버스 프록시.',
    'settings.server.allowedIps.help' => '루프백 외에 연결이 허용되는 클라이언트 IP 또는 CIDR 범위; 그 외에는 로그인 전에 403으로 거부됨. 비어 있으면: 주소 필터 없음.',
    'settings.server.allowedOrigins.help' => '서버가 자체 오리진 외에 추가로 허용하는 브라우저 오리진 (http(s)://host[:port])',
    'settings.server.askTimeoutSeconds.help' => '권한 요청이 거절되기 전 클라이언트 대기 시간(초); 0은 무한 대기.',
    'settings.server.browseRoot.help' => 'server.dirBrowse 디렉터리는 (--browse-root와 동일)으로 제한됩니다. 미설정 시 홈 디렉터리가 기본값입니다.',
    'settings.server.dirBrowse.help' => '로그인한 클라이언트가 server.browseRoot 아래 디렉터리 이름을 나열하고 해당 위치에서 세션을 시작할 수 있도록 허용 (--allow-dir-browse와 동일). 기본값: 꺼짐.',
    'settings.server.clientTools.help' => 'Let Write-scope clients register tools over tools.client.register so the model can call code that runs in the client itself (client__* tools). Off by default.',
    'settings.server.drainSeconds.help' => '서버 중지 시 실행 중인 턴을 취소하기 전 대기 시간(초); 0이면 즉시 중지.',
    'settings.server.host.help' => '`serve`가 바인딩하는 주소. loopback 외의 주소는 실행 시 --allow-remote도 필요.',
    'settings.server.maxConcurrentTurns.help' => '서버가 모든 세션에서 동시에 실행하는 턴 수; 초과 시 busy로 거부됨 (재시도 가능).',
    'settings.server.maxOpenSessions.help' => '서버가 동시에 유지하는 세션 수; 초과 시 가장 오래 유휴인 세션이 해제됨.',
    'settings.server.port.help' => '`serve`가 바인딩할 포트; 0이면 사용 가능한 포트를 선택합니다.',
    'settings.server.trustedProxies.help' => '서버가 신뢰하는 X-Forwarded-For / X-Forwarded-Proto의 IPs 또는 CIDRs.',
    'settings.serviceTier.help' => '프리미엄 레인은 페어가 정한 경로로 전송됩니다: openai는 Chat과 Responses 양쪽 모두에서 `service_tier: "priority"`를 요청하고, anthropic은 `speed: "fast"`를 요청합니다 (claude-opus-5-5 GA 계열 및 claude-opus-5 / claude-opus-4-8 research-preview 계열만 해당, 필수 beta 헤더는 자동 적용); 미설정 또는 인식 불가 시 요청 없음. Fast 모드는 모델별 가격표로 산출할 수 없는 프리미엄 요금을 부과합니다: 티어드 페어가 활성인 동안 해당 턴은 장부에 미가격 상태로 기록되며, 추정 요율로는 절대 기록되지 않습니다. 시작 시 및 모든 provider 또는 모델 재구축 시 적용됩니다.',
    'settings.sessionRetentionDays.help' => '매 실행 시 이 일수 동안 변경되지 않은 이름 없는·고정되지 않은 세션을 삭제하고 삭제 대상 알림; 0(기본값)은 모두 유지.',
    'settings.sessions.autoTitle.help' => '새 세션의 첫 턴에서 제목 모델 호출 한 번으로 이름을 지정합니다. 꺼두면 /rename 전까지 이름이 지정되지 않습니다.',
    'settings.sessions.awayRecap.help' => '터미널이 3분 이상 비활성 후 포커스 복귀를 보고하면 세션이 중단된 지점의 요약을 1회 출력합니다(부재마다 타이틀 모델 호출 1회); off로 설정하면 복귀 시 조용히 처리됩니다. `/recap`으로 언제든지 요약을 요청할 수 있습니다.',
    'settings.skills.listingMaxBytes.help' => '시스템 프롬프트 내 전체 스킬 목록의 바이트 한도; 초과하는 스킬은 "N more skills" 한 줄로 축약됩니다.',
    'settings.skills.pathNudges.help' => '도구가 경로 범위 스킬이 다루는 파일에 접근하면, 해당 스킬의 존재를 모델에게 스킬당 한 번 알림.',
    'settings.statusLine.help' => '{"type": "command", "command": "…", "refreshSeconds": 2}: 출력으로 상태 표시줄을 그리는 셸 명령, refreshSeconds마다 재실행 (2~3600, 기본값 2). stdin으로 세션을 하나의 JSON 문서로 수신 (session_id, cwd, model, workspace, version, cost, candy_code 추가 필드); stdin을 읽지 않는 명령도 실행됨.',
    'settings.streamHeaderTimeoutSeconds.help' => '연결된 스트리밍 서버가 응답 헤더를 전송하는 데 허용되는 시간(초); 전체 요청 타임아웃이 아님.',
    'settings.streamIdleTimeoutSeconds.help' => '스트리밍 응답의 단일 읽기가 연결을 종료로 간주하기 전까지 바이트를 대기할 수 있는 시간(초); 읽기별 값이며 총합이 아님.',
    'settings.subagentMaxActive.help' => '한 세션에서 동시에 실행 가능한 위임 작업 수(모든 레벨, 멤버, 백그라운드 에이전트 포함); 초과 시 `Task` 호출이 거부됨. 미설정(기본값) 또는 0이면 제한 없음.',
    'settings.subagentMaxConcurrent.help' => '한 배치에서 동시에 실행되는 `Task` 호출 수(나머지는 빈 슬롯 대기), 그리고 모든 에이전트 풀의 폭. 미설정(기본값) 또는 0이면 상한 없음.',
    'settings.subagentMaxDepth.help' => '위임된 실행이 세션 아래로 내려갈 수 있는 레벨 수; 마지막 레벨의 실행은 `Task`를 받지 못함. 1이면 하위 에이전트가 더 이상 위임할 수 없음.',
    'settings.subagentMaxTurns.help' => '프리셋에 `maxTurns`가 선언되지 않은 서브 에이전트 — `Task` 위임, 워크플로 단계 또는 `executeAgents` 실행 — 의 단계 상한.',
    'settings.subagentModel.help' => '위임된 하위 에이전트가 프리셋에 `inherit`로 지정된 경우 사용하는 모델; 미설정 시 세션의 모델을 따릅니다.',
    'settings.summaryModel.help' => '압축 요약을 작성하는 모델; 미설정 시 대화 자체의 모델을 사용하며, 프롬프트 캐시를 재사용합니다.',
    'settings.symbolMap.enabled.help' => '순위 매겨진 심볼 단위 저장소 맵을 시스템 프롬프트에 포함하며, 세션당 한 번 캡처합니다.',
    'settings.temperature.help' => '요청에 지정되지 않은 경우 `custom` 프로바이더가 보내는 샘플링 온도.',
    'settings.terminalBackground.help' => '적응형 테마가 텍스트 배경으로 가정하는 값: auto는 터미널에 문의(OSC 11, 그 다음 COLORFGBG); light 또는 dark는 직접 지정.',
    'settings.testCommand.help' => '프로젝트 루트에서 테스트를 실행하는 셸 명령(`composer test`, `pytest -q`); `autoTest`가 실행하는 명령.',
    'settings.theme.help' => '색상 테마; /theme와 팔레트로 실시간 변경. 사용자 테마는 ~/.candy-code/themes의 JSON 파일에서 로드.',
    'settings.thinkingBudget.help' => '추론 토큰 예산: `vertex` 프로바이더의 Gemini `thinkingConfig`; `anthropic` 프로바이더의 확장 추론(Messages API 하한 1024, 0 또는 미설정 시 양쪽 모두 비활성). 추론 토큰은 출력으로 과금.',
    'settings.titleModel.help' => '세션 이름 지정 및 프롬프트 제안 작성 모델; 미설정 시 블록 모델보다 프로바이더 유형의 저가 보조 기본값을 사용.',
    'settings.transcriptJsonl.help' => '커밋된 모든 트랜스크립트를 `~/.candy-code/transcripts/<project>/` 하의 추가 전용 JSONL 저널(파일 0600)에 미러링하고, 훅 스크립트에 해당 경로를 가리키는 `transcript_path` stdin 키를 전달. 저널은 원본 대화를 무제한으로 저장; 시작 시 읽으므로 변경은 다음 시작 시 적용.',
    'settings.toolInstructionCapBytes.help' => 'Edit, Write 또는 ApplyPatch 결과가 담을 수 있는 지배적 CLAUDE.md/AGENTS.md 본문의 최대 바이트 수; 초과분은 마커와 함께 잘림.',
    'settings.toolOutputCapBytes.help' => 'Bash, Grep, Glob, Lsp 또는 WebFetch 결과가 모델에 전달할 수 있는 최대 바이트 수; 잘린 부분은 결과가 지정한 파일에 저장.',
    'settings.toolOutputPreviewLines.help' => '트랜스크립트에 표시되는 접힌 도구 결과의 줄 수; Ctrl+O로 나머지 펼침.',
    'settings.toolSpillCaptureBytes.help' => 'Bash 명령 출력(스트림별)의 최대 메모리 보관량, 결과가 잘릴 때 스파일 파일에 저장; 출력 상한보다 작을 수 없음.',
    'settings.toolSpillMinCapBytes.help' => '잘린 도구 결과를 파일에 저장하는 최소 결과 상한; 그 미만이면 잘림만 알림 후 나머지는 버림.',
    'settings.toolSpillWindowPercent.help' => '도구 결과가 컨텍스트 윈도우를 차지할 수 있는 최대 비율; 초과 시 결과를 파일에 저장하고 모델에는 시작과 끝만 표시.',
    'settings.trustedProjectCommands.help' => '슬래시 명령에서 !`cmd` 셸 블록을 실행할 수 있는 프로젝트 루트.',
    'settings.trustedProjectHooks.help' => '.candy-code/hooks.yaml을 실행할 수 있는 프로젝트 루트.',
    'settings.trustedProjectMcp.help' => '.mcp.json 서버를 시작할 수 있는 프로젝트 루트.',
    'settings.trustedProjectSettings.help' => '.candy-code/settings*.json이 프로젝트 티어 키를 설정할 수 있는 프로젝트 루트.',
    'settings.turnIdleTimeoutSeconds.help' => '실행 중인 턴이 진행 없이 멈춤으로 종료되기까지의 최대 대기 시간(초); 유휴 시간만, 총합 아님.',
    'settings.ui.imageRenderMode.help' => '생성된 이미지를 터미널에 렌더링하는 방식; `auto`는 터미널이 보고하는 최적 프로토콜을 선택.',
    'settings.ui.mediaDisplayOverrides.help' => '렌더 모드별 표시 조정(크기 상한, 대체); 키는 렌더 모드 이름, 값은 표시 설정.',
    'settings.vimMode.help' => '초안 상자의 NORMAL/INSERT 편집(i a I A o O Esc, h j k l w b e 0 $ x, dd D cc C yy y p P v V, text objects di" da( ciw, counts 3dd d2w): NORMAL에서 이동·변경·삭제·복사, INSERT에서 원문 입력. 바인딩이 아닌 모드 — /keys에 표시되지 않음. 저장 후 다음 키 입력 시 적용.',
    'settings.voice.apiKey.help' => '전사 엔드포인트가 요구하는 경우 전송하는 Bearer 키; 리터럴보다 `${VAR}` 플레이스홀더 형식 권장.',
    'settings.voice.baseUrl.help' => 'OpenAI 호환 전사 엔드포인트의 HTTP 기본 URL(끝의 `/v1` 유지); 녹음 데이터는 해당 URL로만 전송. 기본값 없음: 사용자 티어에 설정하기 전까지 음성 입력은 OFF 유지.',
    'settings.voice.language.help' => '전사 언어를 강제하는 BCP-47 코드(`en`, `de`); 미설정 시 엔드포인트가 감지.',
    'settings.voice.maxSeconds.help' => '1회 녹음의 최대 시간(초)(5-600, 기본 120). 상한이 녹화 인자에 포함되므로 고아 녹음도 자동 종료.',
    'settings.voice.model.help' => '모든 전사 요청에 전송하는 모델 ID; OpenAI 호환 엔드포인트에서 `whisper-1`이 응답.',
    'settings.watchFiles.help' => '저장된 파일에 AI!(변경 요청) 또는 AI?(질문)로 끝나는 주석이 있으면 프롬프트 전송; 일반 AI 주석은 컨텍스트로 포함. 채팅 유휴 시 폴링; 시작 후 저장된 주석만 각 1회 발동. 터미널 세션 전용: 감시자가 터미널 프로세스에서 실행되므로 `candy-code serve`가 호스팅하는 세션은 파일을 감시하지 않음.',
    'settings.webFetchMaxBytes.help' => '가져온 본문의 최대 메모리 보관량; 메모리 상한이며, 모델에 전달되는 것은 출력 상한.',
    'settings.webFetchTimeoutSeconds.help' => 'WebFetch 소켓 읽기가 실패하기까지 허용되는 최대 대기 시간(초).',
    'settings.webSearchBackend.help' => 'WebSearch가 쿼리하는 검색 서비스: `searxng`(기본)은 모든 쿼리를 설정된 `webSearchEndpoint`로 전송; `brave`, `tavily`, `exa`는 해당 서비스의 고정 호스트로 연결하며 각각 환경 변수에 API 키 필요(`BRAVE_SEARCH_API_KEY`, `TAVILY_API_KEY`, `EXA_API_KEY`), 다른 URL로 지정 불가.',
    'settings.webSearchEndpoint.help' => '신뢰하는 SearXNG 인스턴스의 검색 URL(`https://searx.example.org/search`); 모든 WebSearch 쿼리가 해당 URL로 전송.',
    'settings.webSearchMaxResults.help' => 'WebSearch 요약에 표시되는 결과 수, 각 결과는 제목·URL·발췌.',
    'settings.webSearchTimeoutSeconds.help' => '1회 검색 요청의 최대 허용 시간(초).',
    'settings.webhooks.help' => '훅 이름에서 {secret, prompt, permissionMode?, rate?}로의 맵; POST /api/hooks/{name}이 본문을 프롬프트에 삽입(신뢰할 수 없음으로 이스케이프)하고 백그라운드 세션을 시작. 비어 있으면(기본) 아무것도 마운트하지 않음. rate는 주소별 분당 N회 전달, 훅 전체 합산. bypass-permissions는 시작 시 훅에 대해 거부; 모드 없는 훅은 서버 모드와 기본값 중 더 엄격한 쪽으로 실행. 행에 signature도 지정 가능: {scheme: "github-sha256"|"hmac-sha256", header?, deliveryHeader?}: 라우터는 커스텀 헤더 시크릿 대신 서명 헤더를 통해 행 시크릿으로 원본 본문의 HMAC-SHA256(sha256=<hex>)을 검증(GitHub는 커스텀 헤더를 보낼 수 없으므로); 서명 실패는 동일한 훅별 잠금에 반영, 이미 확인된 전달 ID(GitHub 스키마 기본값 X-GitHub-Delivery; 일반의 경우 설정된 deliveryHeader)는 두 번째 세션 시작 없이 {"ok": true, "duplicate": true}를 응답.',
    'settings.webhooksOut.help' => '엔드포인트 이름에서 {url, secret, events}로의 맵; events는 turn.completed, session.ended, permission.asked, schedule.fired에서 선택한 비어 있지 않은 목록. 비어 있으면(기본) 아웃바운드 연결을 열지 않음. USER 티어에서만 읽기 — 프로젝트 또는 번들 설정으로는 아웃바운드 엔드포인트를 추가할 수 없음. url은 https여야 하며, http는 리터럴 호스트가 localhost 또는 루프백 주소일 때만 허용, userinfo는 절대 포함 불가; secret은 최소 16자이며 각 전달을 X-Candy-Code-Signature(정확한 본문의 sha256=<hex>)로 HMAC-SHA256 서명하고 X-Candy-Code-Timestamp와 페어링. 전달은 이벤트 루프에서 비동기 — 디스패치는 응답을 기다리지 않음: 2초 연결 경계와 10초 POST별 네트워크 상한이 각 전달을 제한(웹훅 상한, LLM 요청 타임아웃 아님), 전송 실패와 5xx 응답은 2/8/30초 재시도 사다리를 오르고, 4xx와 리다이렉트 응답은 리다이렉트를 따르지 않고 거부하므로 첫 회에 최종, 128개 진행 중 전달의 유한 큐는 오버플로 시 새 디스패치를 버리고 메모리를 늘리지 않음. 시작 시 읽기; 맵 변경은 재시작 시 적용.',
    'settings.webhooksOut.refuse' => '사용자 설정의 webhooksOut을 사용할 수 없음: {reason}. 반만 검증된 엔드포인트에 전달하기보다 시작을 거부 — 맵을 수정하거나, 키를 제거하여 아웃바운드 웹훅 없이 실행.',
    // --- end settings help ---

